const r = (lesson, rows, title, explanation, exampleTitle, example, practice, exam, marks, strict) => ({
  lesson, rows, title, explanation, exampleTitle, example, practice, exam, marks, strict,
});
const q = (question, answer) => ({ q: question, a: answer });

export const repairs = [
  r(1, ["S1.01"], "Binary and decimal magnitude prefixes", [
    "Binary prefixes use powers of 1024: kibi (Ki) means 2^10, mebi (Mi) means 2^20, gibi (Gi) means 2^30 and tebi (Ti) means 2^40. Therefore 1 KiB = 1024 bytes, 1 MiB = 2^20 bytes, 1 GiB = 2^30 bytes and 1 TiB = 2^40 bytes.",
    "Decimal prefixes use powers of 1000: kilo (k) means 10^3, mega (M) means 10^6, giga (G) means 10^9 and tera (T) means 10^12. Therefore 1 kB = 1000 bytes, 1 MB = 10^6 bytes, 1 GB = 10^9 bytes and 1 TB = 10^12 bytes. Case and the i in KiB/MiB/GiB/TiB carry meaning."
  ], "2 TiB drive", "2 TiB = 2 x 2^40 = 2,199,023,255,552 bytes. A 2 TB drive is 2,000,000,000,000 bytes, so the labels are not interchangeable.", [
    q("How many bytes are in 4 GiB?", "4 x 2^30 = 4,294,967,296 bytes."),
    q("Which is larger, 1 TB or 1 TiB?", "1 TiB, because 2^40 is greater than 10^12."),
    q("Match kibi, mebi, gibi and tebi to Ki, Mi, Gi and Ti.", "kibi = Ki, mebi = Mi, gibi = Gi and tebi = Ti."),
    q("Convert 3,000,000 bytes to MB.", "3 MB using the decimal prefix mega; kilo, mega, giga and tera use powers of 1000.")
  ], "State the number of bytes represented by 1 GiB and explain why 1 GB represents a different number of bytes.", [["B1", "1 GiB = 2^30 bytes / 1,073,741,824 bytes"], ["B1", "gibi uses a binary power / multiples of 1024"], ["B1", "1 GB = 10^9 bytes / 1,000,000,000 bytes"], ["B1", "giga uses a decimal power / multiples of 1000"]], "Do not accept 'GiB is bigger' without both numerical definitions."),

  r(2, ["S1.02", "S1.03"], "Integer conversion between binary and denary", [
    "Binary is base 2 and uses place values that are powers of 2. Denary is base 10 and uses place values that are powers of 10. A base label identifies the representation; it does not change the integer value.",
    "To convert a binary integer to denary, add the binary place values whose bits are 1. To convert a denary integer to binary, select powers of 2 that sum to the value and write every required bit position, including zeros."
  ], "Convert the same integer in both directions", "10110110 binary = 128 + 32 + 16 + 4 + 2 = 182 denary. Reversing the process, 182 = 128 + 32 + 16 + 4 + 2, so the 8-bit binary representation is 10110110.", [
    q("Convert the binary integer 01001101 to denary.", "77."),
    q("Convert the denary integer 129 to 8-bit binary.", "10000001."),
    q("Why must a base or representation be stated?", "The same digit string can represent different integer values in different number bases.")
  ], "Convert 156 denary to 8-bit binary, then convert your binary answer back to denary as a check.", [["M1", "selects 128 + 16 + 8 + 4"], ["A1", "10011100"], ["M1", "re-expands the binary place values"], ["A1", "returns to 156 denary"]], "Do not award an unlabelled digit string when the base is ambiguous."),

  r(3, ["S1.02", "S1.03"], "Hexadecimal as a base-16 representation", [
    "Hexadecimal is base 16 and uses digits 0 to 9 and A to F. One hexadecimal digit represents one four-bit binary nibble, so grouping from the right gives an exact conversion between binary and hexadecimal integer representations.",
    "To convert hexadecimal to denary, multiply each digit value by its power-of-16 place value. Binary, denary and hexadecimal may encode the same integer value even though their written representations differ."
  ], "Convert D6 hexadecimal", "D6 hexadecimal = 1101 0110 binary. In denary, D6 = 13 x 16 + 6 = 214, so all three representations encode the integer 214.", [
    q("Convert A7 hexadecimal to binary.", "1010 0111."),
    q("Convert 2D hexadecimal to denary.", "2 x 16 + 13 = 45."),
    q("Convert binary 00111100 to hexadecimal.", "3C.")
  ], "Convert the integer 159 denary to hexadecimal and then to 8-bit binary.", [["M1", "159 = 9 x 16 + 15"], ["A1", "9F hexadecimal"], ["M1", "maps 9 to 1001 and F to 1111"], ["A1", "10011111 binary"]], "Do not treat A to F as decimal two-digit values."),

  r(4, ["S1.04", "S1.05"], "Binary addition and fixed-width overflow", [
    "Perform binary addition from the least-significant bit, carrying left when a column total is 2 or 3. Positive and negative integers must be interpreted using the stated representation and fixed bit width.",
    "Overflow occurs when the mathematical result is outside the range representable in the available bits. For unsigned 8-bit addition, a carry beyond bit 7 shows that the true result is greater than 255. For signed arithmetic, compare the result with the signed representable range rather than treating every carry as overflow."
  ], "Add two unsigned 8-bit integers", "11110000 + 00110000 = 1 00100000. The true result is 288, which is outside the unsigned 8-bit range 0 to 255, so the stored eight-bit result cannot represent the mathematical answer and overflow occurs.", [
    q("Add 00110101 and 00010110.", "01001011; the result is 75 and no unsigned overflow occurs."),
    q("Why does 01111111 + 00000001 not overflow as unsigned 8-bit arithmetic?", "The result 10000000 is 128, which remains inside 0 to 255."),
    q("What is the general overflow test?", "The mathematical result lies outside the range representable by the fixed-width binary representation.")
  ], "Add 11001010 and 01110101 as unsigned 8-bit integers and explain the overflow.", [["M1", "correct binary addition and carry method"], ["A1", "1 00111111 / stored result 00111111"], ["B1", "true result needs a ninth bit / exceeds 255"], ["B1", "therefore unsigned 8-bit overflow occurs"]], "Do not infer unsigned overflow only from the leftmost stored bit being 1."),

  r(5, ["S1.02", "S1.03", "S1.04"], "Signed representations and binary subtraction", [
    "One's-complement representation forms a negative integer by inverting every bit of its positive fixed-width value. Two's-complement representation inverts every bit and adds 1. These are binary representations of signed integers, not separate number bases.",
    "Unsigned subtraction can be performed column by column using borrowing, or by adding the two's complement of the subtrahend. For signed two's-complement subtraction A - B, form the two's complement of B and add it to A. Retain the fixed width, interpret the sign bit and check the representable range."
  ], "8-bit 23 - 9", "00010111 - 00001001 becomes 00010111 + 11110111 = 1 00001110. Discard the ninth carry: 00001110 is 14.", [
    q("Calculate 00110110 - 00010100.", "00100010, which is 34."),
    q("In 8-bit two's complement, calculate 7 - 12.", "00000111 + 11110100 = 11111011, which is -5."),
    q("Why is a carry beyond bit 8 discarded?", "The operation has a fixed 8-bit width; the ninth bit lies outside that representation.")
  ], "Using 8-bit two's complement, calculate 18 - 27. Show how subtraction is converted to addition.", [["M1", "27 is 00011011 and its two's complement is 11100101"], ["M1", "adds 00010010 + 11100101"], ["A1", "obtains 11110111"], ["A1", "interprets the result as -9"]], "Do not award the final mark for 247; the result must be interpreted as signed two's complement."),

  r(6, ["S1.02", "S1.03", "S1.06"], "BCD and hexadecimal in practical systems", [
    "BCD encodes each denary digit separately in four bits. For example, 59 becomes 0101 1001, not the pure-binary value 00111011.",
    "Only 0000 to 1001 are valid BCD digit groups. BCD is used where decimal digits must be displayed or processed exactly, such as digital clocks, calculators and financial displays, although it usually uses more bits than pure binary.",
    "Hexadecimal is used as a compact human-readable form of binary. One hex digit represents four bits, so hexadecimal is practical for memory addresses, machine-code/debug displays and colour values."
  ], "Choose representations for a clock and an address", "A clock can encode 407 as BCD 0100 0000 0111 so each displayed denary digit maps to one four-bit group. A binary memory address can be written compactly in hexadecimal because each hexadecimal digit maps exactly to one nibble.", [
    q("Write denary 82 in BCD.", "1000 0010."),
    q("Decode BCD 0011 1001.", "39."),
    q("Why is BCD suitable for a digital clock?", "Each displayed denary digit maps directly to one four-bit group."),
    q("Why is hexadecimal suitable for a memory address?", "It is a compact form of binary with one digit per four-bit nibble.")
  ], "Explain one practical application of BCD and one practical application of hexadecimal.", [["B1", "BCD application such as a digital clock, calculator or financial display"], ["B1", "links BCD to separate exact denary digits"], ["B1", "hexadecimal application such as memory addresses, machine-code/debug output or colour values"], ["B1", "links hexadecimal to compact four-bit grouping"]], "Do not award a named application without explaining why the representation suits it."),

  r(7, ["S1.07"], "Character sets and internal binary character data", [
    "A character set defines a collection of characters and assigns a numeric character code to each one. The code is stored internally in binary; the bit pattern is meaningful only when software interprets it using the agreed character set.",
    "Standard ASCII uses 7-bit codes, extended ASCII uses 8-bit codes, and Unicode provides code points for a much wider range of languages and symbols. Candidates are not expected to memorise particular character codes; a question must provide any code value needed for a conversion."
  ], "Choose a character set for worldwide text", "A messaging system containing English, Chinese and Arabic text needs Unicode because its character repertoire is much wider than ASCII or extended ASCII. The chosen Unicode encoding stores the character codes as binary data.", [
    q("What does a character set assign to each character?", "A numeric character code that can be stored in binary."),
    q("Distinguish standard ASCII from extended ASCII.", "Standard ASCII uses 7 bits/128 codes; extended ASCII uses 8 bits/256 codes."),
    q("Why is Unicode suitable for multilingual text?", "It defines codes for characters from far more languages and symbol systems."),
    q("Must candidates memorise particular ASCII codes?", "No; any required code value should be provided.")
  ], "Explain how the character 'A' is represented internally and why Unicode is preferred to ASCII for a multilingual website.", [["B1", "character set assigns A a numeric code"], ["B1", "numeric code is stored as a binary bit pattern"], ["B1", "Unicode represents a much wider range of characters/languages"], ["B1", "applies the wider repertoire to the multilingual website"]], "Do not accept that changing a font changes the stored character code."),

  r(8, ["S1.08"], "Bitmap file headers, image resolution and screen resolution", [
    "A bitmap file contains pixel data and a file header. The header stores metadata needed to interpret the file, such as its format and image properties; it is not one of the image pixels. When a calculation says to ignore the file header, calculate only width x height x colour depth.",
    "Image resolution is the number of pixels stored in the image, commonly width x height. Screen resolution is the number of physical display pixels available on the screen. They are independent: scaling an image on a screen does not create new captured detail."
  ], "100 x 80 bitmap with an ignored header", "The pixel data is 100 x 80 x 8 = 64,000 bits = 8,000 bytes. Because the question says to ignore the file header, no metadata bytes are added to that total.", [
    q("What is the purpose of a bitmap file header?", "It stores metadata that tells software how to interpret the file; it is separate from the pixel data."),
    q("What does 3840 x 2160 describe for a monitor?", "Its screen resolution: the number of physical display pixels."),
    q("Does a higher screen resolution automatically increase an image file's size?", "No. File size depends on stored image data, not the screen used to view it.")
  ], "A 200 by 100 bitmap uses 24-bit colour. Calculate its pixel-data size in bytes, ignoring the file header, and explain what has been excluded.", [["M1", "200 x 100 x 24 bits"], ["A1", "480,000 bits / 60,000 bytes"], ["B1", "file header contains metadata used to interpret the bitmap"], ["B1", "header data is excluded because the question requests pixel data only"]], "Do not treat the file header as a pixel or silently add an invented header size."),

  r(9, ["S1.09"], "Vector graphics and drawing lists", [
    "Vector encoding stores a graphic as a drawing list of drawing objects. Each object has properties such as type, coordinates, dimensions, line colour, fill colour and line thickness; software redraws the objects from these instructions.",
    "Vectors scale without pixelation and suit logos, diagrams and shapes. Bitmaps store individual pixels and suit photographs or detailed textures. For a given application, the choice must be justified using the source image and intended editing or scaling."
  ], "Store a red circle", "A drawing-list entry could record object = circle, centre = (80, 60), radius = 20, fill = red and outline = black. Enlarging it changes the geometry before redrawing, not a grid of stored pixels.", [
    q("Name two properties stored for a vector object.", "Any two of coordinates, dimensions, fill, line colour or line thickness."),
    q("Choose vector or bitmap for a company logo that must appear on a pen and a billboard.", "Vector, because geometric objects can be scaled without pixelation."),
    q("Why is bitmap normally better for a photograph?", "A photograph contains complex per-pixel colour and texture that is inefficient to describe as drawing objects.")
  ], "A designer creates a simple icon from circles and rectangles. Explain how it is stored as a vector graphic and give one advantage over a bitmap when resized.", [["B1", "stored as a drawing list / list of objects"], ["B1", "stores object properties such as coordinates/dimensions/colour"], ["B1", "software redraws objects from the descriptions"], ["B1", "can be resized without pixelation / loss of shape quality"]], "Do not accept 'vector has better quality' unless scalability or object-based storage is explained."),

  r(10, ["S1.10"], "Sound sampling, sampling resolution and file size", [
    "An analogue sound wave varies continuously. Analogue-to-digital sampling measures its amplitude at regular time intervals, quantises each measurement to one permitted level and stores the resulting sample value as a binary number. The sequence of binary sample values is the digital representation of the sound.",
    "Sampling rate is the number of samples taken per second, measured in hertz (Hz). Sampling resolution is the number of bits used for each sample and therefore controls how many amplitude levels are available. 'Sample resolution' is a common synonym, but sampling resolution is the official syllabus term.",
    "For uncompressed sound, file size in bits = sampling rate x sampling resolution x duration x number of channels. Increasing sampling rate can represent changes over time more accurately; increasing sampling resolution can represent amplitude more accurately. Either increase also makes the file larger when the other factors stay constant."
  ], "Calculate and interpret one recording", "A 10-second mono recording sampled at 8000 Hz with 16-bit sampling resolution uses 8000 x 16 x 10 x 1 = 1,280,000 bits = 160,000 bytes. Doubling only the sampling resolution to 32 bits doubles the file size and provides more possible amplitude levels; it does not take more samples per second.", [
    q("What is the official term for the number of bits used to store each sound sample?", "Sampling resolution; sample resolution is a common synonym."),
    q("How does a higher sampling rate affect the stored data?", "It stores more measurements each second, which can improve time accuracy and increases file size."),
    q("How does a higher sampling resolution affect the stored data?", "It provides more possible amplitude levels, which can improve amplitude accuracy and increases file size.")
  ], "A 5-second stereo recording is sampled at 12,000 Hz using 8-bit sampling resolution. Calculate its uncompressed size in bytes and explain one accuracy/storage trade-off.", [["M1", "uses 12,000 x 8 x 5 x 2 bits"], ["A1", "obtains 960,000 bits / 120,000 bytes"], ["B1", "higher sampling rate gives more measurements per second or higher sampling resolution gives more amplitude levels"], ["B1", "the stated increase improves the relevant accuracy but increases file size"]], "Do not interchange sampling rate and sampling resolution; rate controls measurements per second, while resolution controls bits/levels per measurement."),

  r(12, ["S1.11"], "Compression methods for text, bitmap, vector and sound files", [
    "Compression represents a file using fewer bits. Lossless compression must reconstruct every original bit, so it is required where any change would alter meaning, such as program source or exact text. Lossy compression permanently discards selected detail and is suitable only when the resulting quality remains acceptable for the purpose.",
    "Text can be compressed losslessly by run-length encoding repeated characters or by replacing repeated words/strings with shorter dictionary references. Bitmap data can use run-length encoding when adjacent pixels repeat; lossy bitmap compression may reduce colour precision or discard fine spatial detail. RLE is effective only when the runs save more space than their symbol-count representation.",
    "A vector file stores drawing objects rather than pixels. It can be compressed losslessly by storing repeated shapes or properties once and referring to them, and by removing redundant object descriptions. Sound can use lossless pattern coding when exact samples are required, or lossy perceptual coding that removes less-audible sound information; reducing sample rate or sampling resolution also reduces data but changes the recording.",
    "Method choice depends on file type, repetition, required fidelity and use. A valid justification must connect the chosen method to what may or may not be discarded; naming 'lossy' or 'lossless' alone is not enough."
  ], "Choose methods for four files", "Compress repeated spaces in a text log with RLE or a dictionary without changing the characters; compress a flat-colour bitmap logo with pixel-value RLE; store one repeated vector shape once and reference it; use lossless sound compression for an evidential recording, but perceptual lossy coding may suit streamed music when smaller size is worth a controlled quality loss.", [
    q("Why must program source code use lossless compression?", "Every character must be reconstructed exactly; a discarded or changed character can alter syntax or behaviour."),
    q("When is RLE effective for a bitmap?", "When many adjacent pixels have the same value, so symbol-count pairs use fewer bits than storing each pixel separately."),
    q("How can repeated objects in a vector file be compressed?", "Store the repeated shape/properties once and use shorter references for each occurrence."),
    q("Give one lossy method for sound and its trade-off.", "Remove less-audible frequency/detail information, or reduce sample rate/resolution; the file is smaller but the discarded detail cannot be recovered.")
  ], "For each of text, bitmap, vector and sound data, describe one suitable compression method and state whether it preserves the original data exactly.", [["B1", "text: lossless RLE or dictionary/token substitution with exact reconstruction"], ["B1", "bitmap: RLE for repeated adjacent pixel values, or a valid lossy image method identified as non-exact"], ["B1", "vector: stores repeated objects/properties once and uses references / removes redundant descriptions, losslessly"], ["B1", "sound: lossless pattern coding for exact samples or perceptual lossy coding that removes less-audible detail"], ["B1", "distinguishes exact lossless reconstruction from irreversible lossy removal"], ["B1", "links at least one method to repetition, fidelity or intended use"]], "Do not award generic 'make the file smaller' statements without a method tied to the named media type."),

  r(16, ["S2.01", "S2.04"], "Networking benefits, LAN/WAN and the four required topologies", [
    "Networking devices allow computers and users to share resources such as files, printers, storage and an internet connection. A network can also support communication, collaboration, central account management, central backup and access to shared services. A benefit must identify what is shared or managed and explain the consequence; 'it is easier' is not enough.",
    "A LAN covers a limited geographical area such as one building or site and is normally owned or managed by one organisation. A WAN covers a large geographical area, connects separate LANs or sites and commonly uses telecommunications-provider infrastructure. LAN and WAN describe scope and management, not a guaranteed speed.",
    "In a bus topology, devices attach to one shared backbone cable and a transmitted signal travels along that shared medium. In a star topology, every device has a separate link to a central switch and each frame passes through that switch. In a mesh topology, nodes have multiple interconnections so packets may use alternative routes. A hybrid topology combines two or more topology patterns, for example two star segments connected by a backbone.",
    "Topology choice must be justified from packet path, failure effect, redundancy, cabling cost, expansion and traffic. A star isolates most individual cable faults but the central switch is a single point of failure; a mesh offers alternative paths but needs more links and management; a bus uses less cable but the shared backbone and shared traffic are weaknesses."
  ], "Choose a topology for a two-building clinic", "Use a star LAN inside each building so individual devices have independent links to a central switch. Connect the two stars to form a hybrid network. If the inter-building link is safety-critical, add a second path: packets can use the alternative route after one link fails, at extra cost.", [
    q("State two concrete benefits of networking school computers.", "Shared printers/files/services and central management, backup or communication; each benefit must name its consequence."),
    q("Distinguish a LAN from a WAN using geographical scope and management.", "A LAN covers a limited site and is normally managed by one organisation; a WAN connects sites over a large area and often uses provider infrastructure."),
    q("Describe the packet or signal path in bus, star, mesh and hybrid topologies.", "Bus: shared backbone; star: central switch; mesh: one of several interconnected routes; hybrid: the path follows the combined component topologies."),
    q("Choose star or mesh for a hospital network that prioritises resilience.", "Mesh, because alternative packet routes can maintain communication after a link failure; acknowledge the additional links/cost.")
  ], "A college is replacing one shared bus network with star LANs connected into a hybrid topology. Explain two networking benefits and justify the topology change.", [["B1", "one developed resource-sharing, communication or central-management benefit"], ["B1", "a second distinct developed networking benefit"], ["B1", "star frames pass through a central switch and an individual cable failure normally affects one device"], ["B1", "hybrid combines topology patterns / connects the star segments"], ["B1", "justification links reliability, expansion, traffic or cost to the college"]], "Do not award generic benefits or a topology name without a path/failure consequence."),

  r(18, ["S2.05"], "Packet transmission between two hosts in each required topology", [
    "To describe transmission between two hosts, identify the physical or logical path used. In a bus, the signal travels along the shared backbone and attached devices inspect it. In a star, the source sends a frame to the central switch, which forwards it towards the destination device. In a mesh, packets can be forwarded through one of several alternative routes. In a hybrid, the path follows each component topology, for example source to local switch, across a connecting backbone, then through the destination switch.",
    "Topology justification must connect the packet path to the scenario: central-device failure, backbone failure, individual cable failure, congestion, expansion, redundancy and cabling cost are consequences of the structure."
  ], "Send a patient record across a hybrid hospital network", "The source sends the frame to its ward switch as in a star. The packet crosses the link between ward segments, then the destination switch forwards the local frame to the receiving host. A redundant inter-switch route can keep packets moving after one link fails, but adds cost and management.", [
    q("How is a transmission carried between two hosts in a bus topology?", "The signal travels along the shared backbone and the attached hosts inspect it."),
    q("Where does a frame pass in a star network?", "Through the central switch."),
    q("Why can a mesh continue after one link fails?", "Packets may use an alternative link or route."),
    q("Describe one possible packet path through a hybrid made from two stars.", "Source to its switch, across the link between star segments, then through the destination switch to the receiving host.")
  ], "Compare how a packet travels between two hosts in a star topology and a mesh topology, then justify one topology for a fault-sensitive system.", [["B1", "star packet/frame passes through a central switch"], ["B1", "mesh provides multiple interconnected paths / possible routes"], ["B1", "star switch is a single point of failure"], ["B1", "mesh can use an alternative route when a link fails"], ["B1", "choice is justified from the stated fault-sensitivity and a path consequence"]], "Do not accept 'mesh is better' without a packet-path or failure consequence."),

  r(17, ["S2.02", "S2.03"], "Network models and thin/thick client designs", [
    "In a client-server model, clients request services or resources and one or more servers provide them. Dedicated server roles can include authentication, file storage, web hosting and backup. Central management, consistent access control and central backup are benefits; server cost, specialist administration, dependence on the server and a possible central failure are drawbacks.",
    "In a peer-to-peer model, each peer may request and provide resources directly. It can be inexpensive and simple for a small trusted group because no dedicated server is required, but distributed accounts, backups, security and availability become harder to control. A model choice must be justified from number of users, trust, management, availability, cost and the required shared services.",
    "A thin client relies mainly on a server for processing and/or storage. A thick client performs more processing locally and normally stores more software or data on the client device. Thin clients simplify central updates and can use lower-specification hardware, but depend heavily on the server and network. Thick clients can continue more work when disconnected, but local installation, security and maintenance are distributed."
  ], "Choose a model and client type for a school examination room", "Use a client-server model so accounts, permissions, exam files and backups are controlled by servers. Thin clients support central software management and reduce local storage, but the school must provide resilient servers and networking because a failure can stop the room. Thick clients would reduce that dependence but distribute software and security maintenance.", [
    q("State the roles of a client and server.", "A client requests a service or resource; a server provides and manages the service or resource."),
    q("Give one benefit and one drawback of peer-to-peer networking.", "Benefit: no dedicated server / low setup cost. Drawback: distributed security, backup and availability are harder to manage."),
    q("Justify client-server for 600 managed school users.", "Central accounts, permissions, storage, updates and backup suit many users, despite server cost and availability risk."),
    q("Distinguish a thin client from a thick client.", "A thin client depends mainly on server processing/storage; a thick client performs and stores more locally.")
  ], "A call centre is choosing a client-server model with thin clients. Explain two benefits and two drawbacks of this combined choice.", [["B1", "centralised accounts/software/update or data management"], ["B1", "lower client hardware/storage requirement"], ["B1", "depends on network/server availability or performance"], ["B1", "server infrastructure, administration or central-failure cost"], ["B1", "develops at least one point in the call-centre context"]], "Do not award 'cheaper' unless the lower client specification or central administration explains why; do not confuse network model with topology."),

  r(19, ["S2.11"], "Ethernet collisions and CSMA/CD", [
    "CSMA/CD means Carrier Sense Multiple Access with Collision Detection. A station listens to the shared medium; if idle it transmits, while continuing to detect a collision.",
    "After a collision, stations stop transmitting, send/recognise a jam signal, wait for different random backoff periods and retry. The random delay reduces the chance of another simultaneous attempt."
  ], "Two stations sense an idle cable", "Both may begin before either signal reaches the other. They detect the collision, stop, wait different random periods and the station whose timer expires first retries.", [
    q("What is sensed before Ethernet transmission?", "Whether the shared carrier/medium is idle."),
    q("What happens immediately after a collision is detected?", "Transmission stops and a retry is scheduled after a random backoff."),
    q("Why must the delay be random?", "Different delays reduce repeated simultaneous retransmission.")
  ], "Describe how CSMA/CD handles two devices attempting to transmit on a shared Ethernet medium.", [["B1", "each device listens/senses the carrier before transmitting"], ["B1", "transmits when the medium is idle"], ["B1", "detects a collision and stops transmission"], ["B1", "waits a random/backoff time before retrying"]], "Do not accept collision avoidance: CSMA/CD detects and responds to a collision after transmission has begun."),

  r(20, ["S2.15", "S2.16"], "IP addressing, URL structure and DNS", [
    "IPv4 uses 32-bit addresses; IPv6 uses 128-bit addresses and provides a much larger address space. Subnetting divides a network into logical sections called subnets and uses part of the address to identify the network/subnet.",
    "An IP address is associated with a device's network interface on a network and supplies the logical source or destination used for routing. A public address is routable on the internet; a private address is used inside a private network and is not directly routed across the public internet. This reduces direct unsolicited reachability but does not guarantee security. Static addresses remain fixed; dynamic addresses are allocated and may change.",
    "A Uniform Resource Locator (URL) identifies the location of a resource on the World Wide Web. Its structure can include a scheme such as https, a domain name, an optional port, a path and optional query/fragment. DNS resolves the domain-name part to an IP address; it does not translate the path or store the web resource. The browser then uses the resolved IP address to send packets towards the server and the path to request the resource."
  ], "Locate one resource on a school web server", "For https://portal.school.example:443/results/today, https is the scheme, portal.school.example is the domain name, 443 is the port and /results/today is the path. DNS resolves only the domain name to an IP address. An externally reachable server may use a static public IPv4 or IPv6 address; school laptops may use dynamic private addresses inside a subnet.", [
    q("How many bits are in IPv6?", "128 bits."),
    q("Why might a server use a static IP address?", "Clients/DNS need a predictable address for the service."),
    q("What is the purpose of subnetting?", "To divide a network into logical subnetworks and identify which subnet an address belongs to."),
    q("Identify the scheme, domain and path in https://shop.example.org/items/7.", "Scheme: https; domain: shop.example.org; path: /items/7."),
    q("Which part of that URL is resolved by DNS?", "The domain name shop.example.org; DNS returns its IP address.")
  ], "Compare IPv4 with IPv6, then explain how a URL and DNS are used to request a web resource.", [["B1", "IPv4 uses 32-bit addresses"], ["B1", "IPv6 uses 128-bit addresses / provides a much larger address space"], ["B1", "URL identifies a WWW resource and includes a domain plus resource path"], ["B1", "DNS resolves the domain name to an IP address"], ["B1", "IP address is used to route packets while the path identifies the requested resource"]], "Do not accept that a private IP address guarantees security or that DNS converts the entire URL/stores the website."),

  r(22, ["S2.07", "S2.08"], "Wired and wireless networks with all required transmission media", [
    "A wired network carries signals through a physical cable. It can provide stable, predictable links and avoids radio interference, but installation restricts movement and may require disruptive cabling. A wireless network transmits through the air, supporting mobility and rapid installation, but shared radio capacity, interference, obstacles and interception risk can affect performance and security. The implications must be tied to a given use, not reduced to 'wired is faster'.",
    "Copper cable carries electrical signals and is often economical for short LAN links, but suffers attenuation and electromagnetic interference. Fibre-optic cable carries pulses of light, supports high bandwidth and long distances and is resistant to electromagnetic interference, but equipment and installation may cost more.",
    "Radio waves, including WiFi, support non-line-of-sight local wireless access but can be absorbed, reflected or interfered with. Terrestrial microwave links provide directional point-to-point communication and usually require clear line of sight. Satellite communication uses microwave/radio links to and from a satellite for wide or remote coverage, but long propagation distance can increase latency and weather can affect some links."
  ], "Connect a school campus and a remote weather station", "Use copper for short fixed desktop links, fibre-optic cable between buildings requiring high bandwidth, WiFi radio waves for mobile tablets, a line-of-sight microwave link where cabling between two buildings is impractical, and satellite for the remote station without local cable infrastructure. Each choice follows distance, mobility, interference, bandwidth, latency and cost.", [
    q("Compare wired and wireless networks for fixed desktops and mobile tablets.", "Wired provides a stable physical link for fixed devices; wireless radio supports mobility but may suffer interference, obstacles and shared capacity."),
    q("Compare copper cable with fibre-optic cable.", "Copper uses electrical signals and may be cheaper; fibre uses light, supports higher bandwidth/longer distance and resists electromagnetic interference."),
    q("Distinguish WiFi radio waves, terrestrial microwave and satellite links.", "WiFi provides local wireless access; terrestrial microwave is directional and line-of-sight; satellite provides wide/remote coverage but commonly has greater latency."),
    q("Choose a medium for a remote location with no cable infrastructure.", "Satellite if wide remote coverage is required; justify the latency/cost/weather drawback.")
  ], "Recommend transmission media for fixed classroom PCs, mobile tablets, an inter-building backbone and a remote field station.", [["B1", "copper cable for short fixed links with a valid cost/stability reason"], ["B1", "WiFi/radio waves for mobile devices with an interference/security implication"], ["B1", "fibre-optic cable for the high-bandwidth/longer inter-building link"], ["B1", "satellite for remote coverage without cable infrastructure"], ["B1", "at least one limitation is correctly linked to the chosen medium"]], "Do not accept unqualified 'wireless is less secure' or 'fibre is faster'; require a mechanism or scenario consequence."),

  r(23, ["S2.09", "S2.10", "S2.14"], "Required LAN and internet connection hardware", [
    "A NIC/WNIC provides wired/wireless network access; a WAP connects wireless devices to a LAN; a switch forwards frames within a LAN; a bridge joins LAN segments; a repeater regenerates a weakened signal; a server provides shared services; cables carry wired signals.",
    "A router connects different networks and forwards packets using destination IP addresses and routing information; for example, it connects a LAN to the internet. A router is not simply a device that 'provides WiFi', although one physical home unit may combine router and WAP functions.",
    "A modem converts between the data representation used by a computer/network and the signalling required by an access link. Internet-supporting connections include the PSTN (Public Switched Telephone Network), a dedicated line that provides a permanent link, and a cell phone network (cellular phone network) that supplies radio access through mobile infrastructure."
  ], "Branch office connection", "Each desktop uses a NIC and cable to the switch; phones use a WNIC through the WAP. A server supplies shared files or authentication, a bridge may join LAN segments and a repeater is added only where a weakened signal needs regeneration. The router forwards packets to the ISP through a suitable modem and either the PSTN, a dedicated line or a cell phone network.", [
    q("Which device regenerates a weakened signal?", "Repeater."),
    q("Which component gives a laptop wireless network connectivity?", "WNIC; it connects through a WAP."),
    q("What distinct jobs do a bridge and a switch perform?", "A bridge joins LAN segments; a switch connects LAN devices and forwards frames to the appropriate port."),
    q("Why might a business choose a dedicated line instead of the PSTN?", "It offers a permanent, predictable connection suited to continuous business traffic."),
    q("When may a cell phone network support internet access?", "When a device or site uses cellular radio infrastructure instead of a fixed access line.")
  ], "Describe the hardware path used when a wireless laptop accesses an internet server through a dedicated line.", [["B1", "WNIC provides the laptop's wireless network interface"], ["B1", "WAP connects the laptop to the LAN and switch forwards the local frame"], ["B1", "router forwards packets between the LAN and internet/other networks"], ["B1", "modem/interface converts data for the access-link signalling"], ["B1", "dedicated line provides the permanent external connection"]], "Do not merge NIC/WNIC, WAP, switch, router and modem roles; a combined physical box does not make the logical functions identical."),

  r(24, ["S2.06", "S2.13"], "Public/private cloud and WWW/internet distinction", [
    "The internet is the global network infrastructure and protocols connecting networks. The World Wide Web is one service using that infrastructure: linked web resources accessed using browsers and HTTP/HTTPS.",
    "A public cloud offers shared provider infrastructure to customers; a private cloud is dedicated to one organisation. Public cloud can scale with lower capital cost but gives less direct control; private cloud offers more control/customisation but costs more to operate."
  ], "Company document system", "A small company may choose public cloud storage for rapid scaling and outsourced maintenance. A regulated organisation may choose a private cloud for control over configuration and data location, accepting higher cost.", [
    q("Is email part of the WWW?", "No. It uses the internet but is a separate internet service."),
    q("Who uses the infrastructure in a private cloud?", "One organisation."),
    q("Give one public-cloud drawback.", "Less direct control, provider dependence, privacy/location concerns or internet dependence.")
  ], "Distinguish the internet from the World Wide Web, then explain one benefit of a private cloud for an organisation.", [["B1", "internet is the network infrastructure / interconnected networks"], ["B1", "WWW is a service of linked web resources using the internet"], ["B1", "private cloud infrastructure is dedicated to one organisation"], ["B1", "greater control/security configuration/customisation developed"]], "Do not accept 'the internet is WiFi' or 'the WWW is the internet'."),

  r(25, ["S2.12"], "Bit streaming, bit rate and broadband", [
    "Bit streaming delivers media progressively so playback can begin before the whole file arrives. Real-time streaming carries a live event with minimal delay; on-demand streaming sends stored content selected by the user.",
    "Bit rate is the number of bits transmitted each second. Available broadband speed must normally exceed the media bit rate and absorb variation; otherwise the player buffers, lowers quality or pauses. A buffer stores arriving data temporarily."
  ], "6 Mbit/s video on 4 Mbit/s link", "The stream consumes data faster than the link supplies it. A starting buffer only delays the shortage; sustained playback requires a lower bit rate or faster connection.", [
    q("Why does a streaming player buffer data?", "To absorb short variations between arrival and playback rates."),
    q("Classify a live sports broadcast.", "Real-time streaming."),
    q("Classify a selected recorded film.", "On-demand streaming.")
  ], "A video has a bit rate of 8 Mbit/s. Explain why a connection advertised as 8 Mbit/s may still pause during playback.", [["B1", "video requires about 8 million bits each second"], ["B1", "actual available speed may be below advertised/maximum speed"], ["B1", "other traffic, overhead or variation reduces throughput"], ["B1", "buffer empties when data arrives more slowly than playback consumes it"]], "Do not accept 'bandwidth is slow' without comparing arrival rate with the stream bit rate."),

  r(27, ["S3.01"], "Why computer systems need input, output and storage", [
    "Input is needed to enter data and instructions into a computer system. Output is needed to communicate processed information to a user or to cause an action. A processor cannot perform a useful task unless it can receive the required data and make the result available.",
    "Primary memory is needed to hold the instructions and data currently being used by the processor. Secondary storage is needed for non-volatile, long-term retention of programs and data. Removable storage is secondary storage that can be disconnected, so it can transfer data or hold an offline backup, although it can be lost or stolen."
  ], "Field survey tablet", "A surveyor enters measurements through a touchscreen, sees validation messages on the display, uses RAM as primary memory while the survey application runs, saves records on internal secondary storage, and copies an encrypted backup to removable storage before leaving the site.", [
    q("Why does a computer system need input?", "To receive data and instructions for processing."),
    q("Why does a computer system need output?", "To communicate processed information or cause an action."),
    q("Distinguish the need for primary memory from the need for secondary storage.", "Primary memory holds instructions/data currently in use; secondary storage retains programs/data long term without power."),
    q("Give one purpose of removable storage.", "To transfer data between systems or keep a detachable/offline backup copy.")
  ], "A portable medical system receives patient measurements, processes them and stores the records. Explain why it needs input, output, primary memory, secondary storage and removable storage.", [["B1", "input receives patient measurements/data"], ["B1", "output communicates results or warnings"], ["B1", "primary memory holds current program instructions and working data"], ["B1", "secondary storage retains patient records long term without power"], ["B1", "removable storage supports transfer or an offline/detachable backup"]], "Do not treat primary memory, secondary storage and removable storage as interchangeable terms."),

  r(28, ["S3.03"], "Microphone, touchscreen and VR headset operation", [
    "A microphone diaphragm vibrates with sound; a transducer converts the movement into an analogue electrical signal, which an ADC samples into digital values. A capacitive touchscreen detects a change in an electric field and calculates touch coordinates.",
    "A VR headset displays a separate view to each eye and uses motion/orientation sensors to update the viewpoint. Low-latency tracking is needed so the displayed scene follows head movement."
  ], "Turn head in VR", "Gyroscope/accelerometer readings report orientation; the processor calculates a new camera view; displays present updated left/right images, creating stereoscopic depth.", [
    q("What converts a microphone's analogue signal into digital samples?", "An analogue-to-digital converter (ADC)."),
    q("What does a capacitive touchscreen detect?", "A change in capacitance/electric field at a touch location."),
    q("Why does a VR headset track head movement?", "To update the displayed viewpoint to match the user's orientation.")
  ], "Describe how a microphone captures sound for storage in a computer.", [["B1", "sound waves vibrate a diaphragm"], ["B1", "transducer converts vibration to an analogue electrical signal"], ["B1", "ADC samples/measures the signal"], ["B1", "sample values are encoded/stored as binary"]], "Do not accept that the microphone directly records binary without an analogue signal and conversion stage."),

  r(29, ["S3.03", "S3.04"], "Laser/3D printers, speakers and output buffers", [
    "A laser printer charges a drum, a laser discharges selected points, toner adheres to the image, toner transfers to paper and heat/pressure fuse it. A 3D printer deposits or solidifies material layer by layer from a digital model.",
    "A speaker uses a DAC/amplifier to drive a coil and cone, producing pressure waves. An output buffer temporarily holds data because the processor can produce it faster or in different-sized bursts than a printer or audio device can consume it."
  ], "Print a page", "The operating system places page data in a print buffer. The CPU can continue other work while the slower printer consumes buffered data and performs drum, toner and fusing stages.", [
    q("What permanently bonds toner to laser-printer paper?", "Heat and pressure in the fuser."),
    q("How does a 3D printer build an object?", "It deposits/solidifies successive layers."),
    q("How does a speaker produce sound from digital output?", "A DAC and amplifier drive a coil and cone; cone vibration produces pressure waves in the air."),
    q("Why is a print buffer needed?", "It handles the speed difference and lets the producer continue while the printer consumes data.")
  ], "Explain why a buffer is used when a computer sends a large document to a laser printer.", [["B1", "processor/computer and printer operate at different speeds"], ["B1", "buffer temporarily stores print data"], ["B1", "printer reads data at its own rate"], ["B1", "computer/processor can continue other processing without waiting for the full print"]], "Do not accept 'the buffer makes the printer faster'; it manages transfer-rate differences."),

  r(30, ["S3.05", "S3.06", "S3.07"], "RAM, ROM and their principal technologies", [
    "RAM is volatile read/write primary memory used for programs and data currently being processed. ROM is non-volatile primary memory used for instructions that must remain when power is removed, such as firmware or start-up instructions. ROM is not ordinary long-term storage for user files.",
    "SRAM stores bits using flip-flop circuits, needs no refresh and is fast but expensive with lower density, so it is used for cache. DRAM stores charge in capacitors, requires refresh and is slower but cheaper and denser, so it is used for main memory.",
    "PROM is programmed once. EPROM can be erased with ultraviolet light and reprogrammed. EEPROM is erased and rewritten electrically, often without removing it from the system. All three are non-volatile ROM technologies."
  ], "Choose memory for a computer system", "Use DRAM as main RAM because its density and lower cost support a large working capacity. Use a small amount of SRAM for cache because faster, no-refresh access reduces processor waiting. Store updateable firmware in EEPROM because it remains without power but can be rewritten electrically.", [
    q("Distinguish RAM from ROM by volatility and use.", "RAM is volatile and holds current programs/data; ROM is non-volatile and holds persistent firmware or start-up instructions."),
    q("Why is DRAM refreshed?", "Charge in its storage capacitors leaks and must be restored."),
    q("Why is SRAM used for cache while DRAM is used for main memory?", "SRAM is faster and needs no refresh; DRAM is denser and cheaper per bit for a larger capacity."),
    q("Distinguish PROM, EPROM and EEPROM.", "PROM is programmed once; EPROM is erased with ultraviolet light; EEPROM is erased and rewritten electrically.")
  ], "Compare SRAM and DRAM and explain why DRAM is normally used for main memory.", [["B1", "SRAM is faster / does not require refresh"], ["B1", "DRAM requires refresh / is slower"], ["B1", "DRAM has greater density / lower cost per bit"], ["B1", "main memory needs large capacity, making DRAM more economical"]], "Do not award both comparison marks for merely expanding the abbreviations."),

  r(31, ["S3.03"], "HDD, flash and optical reader/writer operation", [
    "An HDD spins magnetic platters while an actuator positions read/write heads; writing changes magnetic orientation and reading senses it. Flash memory stores charge in floating-gate cells and has no moving parts.",
    "An optical drive spins a disc and directs a laser at its track. Reflected-light differences are read as data; a writer uses a higher-power laser to change a dye or recording layer."
  ], "Read an HDD block", "The controller moves the head to the correct track, waits for the sector to rotate beneath it, senses magnetic patterns and transfers the decoded bits through a buffer.", [
    q("Why is flash storage resistant to mechanical shock?", "It has no moving read/write head or spinning platter."),
    q("What physical property stores HDD data?", "Magnetic orientation/patterns on a platter."),
    q("How does an optical reader distinguish stored data?", "It detects differences in reflected laser light.")
  ], "Describe how data is read from a magnetic hard disk drive.", [["B1", "platters rotate"], ["B1", "actuator positions read/write head over the required track"], ["B1", "required sector passes beneath the head"], ["B1", "head senses magnetic patterns which are decoded as data"]], "Do not accept a laser-based explanation for an HDD; lasers apply to optical media."),

  r(33, ["S3.02"], "Embedded systems: purpose, benefits and drawbacks", [
    "An embedded system is a computer system built into a larger device to perform one dedicated task or a closely related set of tasks. A microcontroller may integrate the processor, memory and input/output interfaces needed for that task.",
    "Benefits can include low cost, low power use, small size and reliable, predictable automatic operation because the hardware and software are designed for a limited purpose. Drawbacks can include limited processing, storage and user interface, difficulty adding new functions, and dependence on the embedded controller: if it fails, the larger device may stop working. A valid comparison must link each point to the device and task."
  ], "Washing-machine controller", "A dedicated microcontroller can read sensors and control the motor and valves with low power use and predictable timing. Its limited interface is acceptable for wash programs, but it cannot readily run unrelated applications, and a controller failure can prevent the whole machine from operating.", [
    q("What two features define an embedded system?", "It is built into a larger device and performs a dedicated task or closely related set of tasks."),
    q("Give one benefit of an embedded controller and explain its consequence.", "For example, low power use reduces energy or battery demand for the device."),
    q("Give one drawback of an embedded controller and explain its consequence.", "For example, limited resources make it difficult to add unrelated functions or run general-purpose software."),
    q("Why can failure of an embedded controller be serious?", "The larger device may lose the function controlled by that computer or stop operating.")
  ], "A battery-powered medical monitor uses an embedded controller. Explain two benefits and two drawbacks of this design in context.", [["B1", "benefit such as low power, compact size or predictable automatic operation"], ["B1", "first benefit linked to battery life, portability or continuous monitoring"], ["B1", "drawback such as limited resources/upgrading/interface or controller dependence"], ["B1", "first drawback linked to limited new functions or device failure"], ["B1", "second distinct benefit or drawback correctly developed"]], "Do not award bare adjectives such as 'small' or 'cheap' without a device-specific consequence."),

  r(34, ["S3.08", "S3.09"], "Monitoring, control, feedback and required sensors", [
    "A monitoring system uses sensors to collect data for recording, display or alerts; it does not necessarily change the environment. A control system uses sensor input and a stored rule or target to send output to an actuator. In closed-loop control, feedback is the new sensor reading produced after the action, allowing the controller to adjust or stop the output.",
    "A temperature sensor measures temperature, a pressure sensor measures force per unit area or pressure, an infra-red sensor detects infra-red radiation, and a sound sensor detects sound level or sound waves. The sensor supplies input data; it does not itself decide or perform the control action.",
    "Choose a sensor by matching the physical quantity to the application: temperature for a greenhouse, pressure for a tyre or burglar mat, infra-red for a remote-control receiver or beam alarm, and sound for a noise monitor. A light-intensity sensor is useful supporting context but does not replace the named infra-red and sound sensors."
  ], "Greenhouse monitoring and control", "A monitoring system records and displays temperature readings. A control system also compares each reading with a threshold and activates a fan motor actuator when the greenhouse is too hot. New temperature readings provide feedback, so the fan can stop when the target is reached.", [
    q("Distinguish monitoring from control.", "Monitoring records, displays or reports sensor data; control uses data to change an actuator or system state."),
    q("What is feedback in a closed-loop control system?", "A new sensor reading after the action, used to adjust or stop the output."),
    q("Which named sensor detects radiation used by a remote control?", "An infra-red sensor."),
    q("Which named sensor is suitable for a classroom noise monitor?", "A sound sensor."),
    q("Why is a sensor not an actuator?", "A sensor supplies input about a physical quantity; an actuator produces a physical output action.")
  ], "A greenhouse system records temperature and automatically opens a vent when necessary. Distinguish its monitoring and control functions and explain the feedback cycle.", [["B1", "monitoring records/displays temperature readings"], ["B1", "control compares a reading with a rule/threshold"], ["B1", "controller sends output to a vent motor or other actuator"], ["B1", "new sensor readings provide feedback after the action"], ["B1", "feedback is used to adjust or stop the actuator"]], "Do not state that monitoring necessarily changes an actuator, or that a sensor performs the control decision."),

  r(37, ["S3.10"], "Logic-gate symbols, functions and representation conversions", [
    "Use the standard symbols and exact functions of NOT, AND, OR, NAND, NOR and XOR (EOR). NOT has one input; each of the other five gates has two inputs for this syllabus. A truth table lists every input combination and the resulting output according to the gate or circuit function.",
    "You must be able to construct a logic circuit from a problem statement, logic expression or truth table; construct a truth table from a problem statement, logic circuit or logic expression; and construct a logic expression from a problem statement, logic circuit or truth table. Move through variables and conditions first, then intermediate gate outputs, then the final output so every representation can be checked against the same rows."
  ], "Convert one rule among four representations", "Rule: an alarm sounds when the system is armed and either the door or window is open. Define A, D and W; write Alarm = A AND (D OR W); draw an OR gate for D and W feeding an AND gate with A; then list all eight input combinations and evaluate the intermediate OR column before Alarm.", [
    q("What distinguishes the XOR symbol from the OR symbol?", "XOR has an additional curved line on the input side."),
    q("How many inputs does NOT have, and how many do the other specified gates have in this syllabus?", "NOT has one input; AND, OR, NAND, NOR and XOR each have two inputs."),
    q("Name the three possible sources from which a logic circuit may be constructed.", "A problem statement, a logic expression or a truth table."),
    q("How do intermediate columns help convert a circuit into a truth table?", "Each intermediate column records one gate output, allowing the final result to be calculated and checked row by row.")
  ], "A truth table gives output 1 only when input A is 1 and input B is 0. Construct a logic expression and describe the corresponding circuit.", [["B1", "identifies that B must be inverted"], ["M1", "constructs expression Q = A AND NOT B"], ["B1", "B is connected to a NOT gate"], ["A1", "A and the NOT-gate output are connected to an AND gate whose output is Q"]], "Do not accept XOR: XOR is also 1 for A=0, B=1, which contradicts the given truth table."),

  r(41, ["S4.01", "S4.03"], "Von Neumann architecture and CPU components", [
    "The basic Von Neumann architecture uses one immediate access store for the instructions and data currently required. This is the stored-program concept: program instructions are stored in memory as binary values alongside data, and the processor fetches instructions from memory rather than being physically rewired for each program.",
    "The control unit (CU) fetches and decodes instructions and sends control signals. The arithmetic and logic unit (ALU) performs arithmetic and logical operations. Registers provide small, fast temporary storage, buses carry addresses, data and control signals, and the system clock supplies regular timing pulses that synchronise state changes.",
    "The immediate access store (IAS) is processor-accessible main memory, not a register, cache or secondary-storage device. A program held on secondary storage must be loaded into IAS before its instructions can be fetched and executed normally."
  ], "Run one stored program", "A program and its input data are copied from SSD into IAS. The PC supplies the address of the next instruction; the instruction is fetched through MDR into CIR, the CU decodes it, and the ALU or another component carries out the operation. The same memory can hold an instruction at one address and data at another because their use is determined by the fetch and instruction semantics.", [
    q("What is the stored-program concept?", "Program instructions are stored in memory in binary form alongside data and are fetched by the processor for execution."),
    q("Why is this a Von Neumann model?", "The basic model uses the same directly accessible memory for instructions and data."),
    q("Distinguish the ALU from the CU.", "The ALU performs arithmetic and logical operations; the CU decodes instructions and coordinates components using control signals."),
    q("What does the system clock do?", "It supplies regular timing pulses that synchronise processor operations and state changes."),
    q("Why is IAS not a CPU register?", "IAS is processor-accessible main memory for current instructions and data; registers are smaller temporary locations inside the CPU.")
  ], "Explain how the Von Neumann stored-program concept, IAS, CU, ALU and system clock cooperate when a program runs.", [["B1", "instructions and data are stored together in IAS/main memory"], ["B1", "program instructions are represented in binary and fetched from memory"], ["B1", "CU fetches/decodes and sends control signals"], ["B1", "ALU performs arithmetic or logical operations"], ["B1", "clock supplies regular timing pulses to synchronise operations"], ["B1", "IAS is directly accessible memory rather than a register or secondary storage"]], "Do not accept that instructions are permanently built into the CU, that IAS is cache, or that the ALU decodes instructions."),

  r(42, ["S4.07"], "Register-transfer notation for the fetch-decode-execute cycle", [
    "Register-transfer notation describes a data transfer or register update. The arrow <- means 'is loaded with' or 'receives'; it is not an equality sign. Memory[MAR] means the contents of the memory location whose address is currently held in MAR.",
    "A coherent fetch sequence is MAR <- PC; MDR <- Memory[MAR]; CIR <- MDR; and PC <- PC + 1 at an appropriate point before the next fetch. The control unit then decodes the opcode and operand in CIR and sends control signals for execution.",
    "During execution, notation such as ACC <- ACC + MDR records an arithmetic result in ACC, while Memory[MAR] <- MDR records a memory write. Read every statement from right to left: obtain the source value, then replace the destination contents.",
    "The exact timing of PC increment may vary between coherent processor descriptions, but MAR must receive the current instruction address before that address is replaced. Register-transfer notation describes movement and updates; it does not imply that two registers permanently contain the same value."
  ], "Trace one instruction fetch", "Start with PC = 120 and Memory[120] = LDD 500. MAR <- PC puts 120 in MAR. MDR <- Memory[MAR] puts LDD 500 in MDR. CIR <- MDR copies the instruction into CIR. PC <- PC + 1 makes PC 121, ready to address the next instruction. The control unit then decodes LDD and executes it.", [
    q("What does MAR <- PC mean?", "Copy the address currently in PC into MAR; PC is not changed by that transfer."),
    q("What does MDR <- Memory[MAR] mean?", "Read the contents of the memory location addressed by MAR into MDR."),
    q("Why is CIR <- MDR needed during fetch?", "It places the fetched instruction in CIR so the control unit can decode its opcode and operand."),
    q("Write register-transfer notation for adding the value in MDR to ACC.", "ACC <- ACC + MDR.")
  ], "Using register-transfer notation, describe the fetch of one instruction and explain the meaning of Memory[MAR].", [["M1", "MAR <- PC"], ["M1", "MDR <- Memory[MAR]"], ["M1", "CIR <- MDR"], ["M1", "PC <- PC + 1 at a coherent point"], ["B1", "Memory[MAR] means the contents at the memory address held in MAR"], ["B1", "CIR is decoded and control signals initiate execution"]], "Do not accept PC <- MAR as the first transfer or treat Memory[MAR] as the address value itself."),

  r(43, ["S4.02"], "General-purpose and special-purpose registers", [
    "A general-purpose register can temporarily hold data or intermediate results for a range of operations. A special-purpose register has a defined processor role. In the CPU-architecture requirement, the named roles are PC, MDR, MAR, ACC, IX, CIR and the status register. In Cambridge assembly-language questions, ACC is the only available general-purpose working register; this question convention does not remove the defined roles of the other named registers.",
    "PC holds the address of the next instruction; MAR holds the address currently being accessed; MDR holds data or an instruction being transferred to or from memory; CIR holds the current instruction while it is decoded or executed.",
    "ACC holds an intermediate or final ALU result. IX holds an offset used to form an indexed effective address. The status register holds flags about an operation or processor state, such as zero, carry or overflow; it does not hold the arithmetic result itself."
  ], "Follow registers through fetch and indexed execute", "PC = 300 is copied to MAR; the instruction read from memory enters MDR and then CIR. If that instruction is LDX 500 while IX = 3, the effective address is 503 and the value at that address is loaded into ACC. A resulting condition can update a flag in the status register.", [
    q("Distinguish a general-purpose register from a special-purpose register.", "A general-purpose register can hold values for varied operations; a special-purpose register has a defined processor role."),
    q("State the roles of PC, MAR, MDR and CIR.", "PC holds the next-instruction address; MAR the accessed address; MDR transferred data/instruction; CIR the current instruction."),
    q("State the roles of ACC, IX and the status register.", "ACC holds ALU results; IX an indexed-address offset; the status register holds flags about results or CPU state."),
    q("Which general-purpose working register is assumed in Cambridge assembly questions?", "The accumulator, ACC."),
    q("Base 120 plus IX 7 gives which indexed effective address?", "127.")
  ], "Distinguish general-purpose and special-purpose registers, then state the roles of PC, MAR, MDR, CIR, ACC, IX and the status register.", [["B1", "general-purpose register can hold values for varied operations; special-purpose register has a defined role"], ["B1", "PC next-instruction address and CIR current instruction"], ["B1", "MAR accessed address and MDR transferred data/instruction"], ["B1", "ACC intermediate/final ALU result"], ["B1", "IX offset used in indexed addressing"], ["B1", "status register stores flags about a result or processor state"]], "Do not swap MAR with MDR, PC with CIR, or claim that the status register stores the calculation result."),

  r(44, ["S4.04", "S4.06"], "System buses and peripheral ports", [
    "The address bus carries the address of the memory or I/O location being accessed and is normally directed from the processor. The data bus carries data and instructions in either direction. The control bus carries control and timing signals in both directions overall, including read/write signals from the CPU and interrupt or status signals toward it.",
    "A memory read uses all three buses: the CPU places the required address on the address bus, sends a read signal on the control bus, and memory returns the requested data or instruction on the data bus. A bus transfers signals; it does not permanently store them.",
    "USB is a general serial interface carrying digital data and often power for peripherals. HDMI carries digital video and audio. VGA carries analogue video and does not carry audio in the standard VGA signal. Port choice must match the peripheral and signal rather than rely on a claim that one connector is always best."
  ], "Read memory, then connect a display", "To read address 240, the CPU puts 240 on the address bus and read on the control bus; memory returns the contents on the data bus. To connect the computer to a modern TV with one digital audio/video cable, choose HDMI. A keyboard or removable drive commonly uses USB, while a legacy analogue display may use VGA.", [
    q("Which bus carries an address, which carries a value, and which carries read/write signals?", "Address bus; data bus; control bus."),
    q("Trace a memory read using the three buses.", "Address on address bus, read signal on control bus, requested data/instruction from memory on data bus."),
    q("Which port commonly carries both digital video and audio?", "HDMI."),
    q("Which named port carries analogue video?", "VGA."),
    q("Give one USB use or facility.", "A digital peripheral connection such as keyboard/storage, often also supplying electrical power.")
  ], "Describe a memory read using the address, data and control buses, then choose USB, HDMI or VGA for one stated peripheral connection.", [["B1", "address bus carries the required memory/I/O address"], ["B1", "control bus carries the read signal"], ["B1", "data bus returns the requested data/instruction"], ["B1", "USB matched to a suitable digital peripheral/data/power use"], ["B1", "HDMI matched to digital video and audio"], ["B1", "VGA matched to analogue video without standard audio"]], "Do not swap the address and data buses or claim that VGA normally carries digital audio."),

  r(45, ["S4.09"], "Assembly language and machine code", [
    "Machine code is the binary instruction form executed directly by a processor. Each bit pattern is interpreted according to that processor's instruction set, so machine code is processor dependent.",
    "Assembly language is a low-level, processor-specific symbolic representation of machine-code instructions. Mnemonics such as ADD make operations easier for a human to read and write, while operands name the value, register or address used. An assembler translates assembly source into the corresponding machine code; assembly is not executed directly as text.",
    "The relationship is close but not based on English spelling: a mnemonic maps to an opcode defined by the target instruction set, and an operand must be encoded in the form required by that instruction. Labels are resolved to addresses during assembly."
  ], "Translate one symbolic instruction", "For a target instruction set, ADD #3 is assembly source: ADD is the mnemonic and #3 is an immediate operand. The assembler selects that processor's binary ADD opcode and encodes the operand. A different processor type may use a different opcode or instruction format, so the same machine-code bit pattern is not portable by assumption.", [
    q("Which language form does the processor execute directly?", "Machine code: binary instructions defined by its instruction set."),
    q("Why is assembly language easier for people to use than machine code?", "It uses symbolic mnemonics, operands and labels instead of raw binary bit patterns."),
    q("What translates assembly language into machine code?", "An assembler."),
    q("Why are both forms processor specific?", "Their operations, opcodes and instruction formats are defined by the target processor's instruction set.")
  ], "Explain the relationship between assembly language and machine code and why an assembler and a target instruction set are required.", [["B1", "machine code consists of binary instructions executed directly by the processor"], ["B1", "assembly uses mnemonics/operands/labels as a symbolic low-level form"], ["B1", "assembler translates assembly source to machine code"], ["B1", "mnemonic maps to an opcode and operands are encoded"], ["B1", "instruction meanings/formats are defined by the processor instruction set"], ["B1", "therefore code for one processor may not execute correctly on another"]], "Do not accept that assembly source is executed directly or that one machine-code instruction has a universal meaning across processors."),

  r(46, ["S4.10", "S4.11", "S4.12", "S4.13"], "Two-pass assembly, program tracing and the instruction set", [
    "The two-pass assembler stages are Pass 1 and Pass 2. Pass 1 scans source, assigns addresses and builds a symbol table for labels, allowing forward references. Pass 2 translates mnemonics/operands using the completed table and produces machine code; invalid mnemonics or unresolved symbols are reported.",
    "The source form <label>: <opcode> <operand> labels an instruction, while <label>: <data> assigns a symbolic address to a memory location containing data. Pass 1 records both kinds of label in the symbol table.",
    "The five instruction groups are data movement (LDM, LDD, LDI, LDX, LDR, MOV, STO), input/output (IN, OUT), arithmetic (ADD, SUB, INC, DEC), unconditional branch and conditional branch. JMP is the unconditional branch instruction; CMP, CMI, JPE and JPN form the compare and conditional branch group. END returns control to the operating system.",
    "Data movement: LDM #n loads immediate n into ACC; LDD <address> loads the directly addressed contents into ACC; LDI <address> follows the address stored at <address>; LDX <address> loads from <address> + IX; LDR #n loads n into IX; MOV <register> moves ACC to IX; STO <address> stores ACC at the address.",
    "Arithmetic: ADD <address> or ADD #n/Bn/&n adds a memory value or immediate denary/binary/hexadecimal value to ACC; SUB has the corresponding forms; INC <register> and DEC <register> change ACC or IX by one.",
    "Control, comparison and I/O: JMP <address> is unconditional. CMP <address> or CMP #n compares ACC directly or with an immediate value. CMI <address> compares using indirect addressing. JPE jumps after a True comparison and JPN after a False comparison. IN inputs one ASCII character code to ACC; OUT outputs the character whose ASCII code is in ACC; END returns control to the operating system.",
    "ACC is the accumulator and IX is the index register. An address can be absolute or symbolic. Prefix # gives immediate denary, B immediate binary and & immediate hexadecimal data. These prefixes and operand forms are part of the instruction semantics, not optional decoration.",
    "To trace a simple assembly-language program, make a table with one row per executed instruction and columns for the current instruction/address, ACC, IX, relevant memory or output, and branch result. Update only the state changed by that instruction, then use the updated PC or branch target to choose the next row; do not trace source lines that a taken jump skips."
  ], "Assemble, classify and trace a short program", "For LDM #5; ADD #3; CMP #8; JPE MATCH; LDM #0; MATCH: OUT; END, the trace gives ACC 5, then 8, then a True comparison. JPE transfers control to MATCH, so LDM #0 is skipped; OUT outputs the character whose ASCII code is 8, and END returns control to the operating system. In LOOP: ADD ONE, LOOP labels an instruction; ONE: 1 labels the data location containing 1.", [
    q("Which pass builds the symbol table?", "Pass 1."),
    q("What does Pass 2 do?", "Pass 2 translates mnemonics and operands into machine code using the completed symbol table."),
    q("What is the difference between LDM #5 and LDD 5?", "LDM loads literal 5; LDD loads the contents of memory address 5."),
    q("What does LDR #7 do?", "It loads the immediate value 7 into the index register IX."),
    q("Classify IN, SUB, JMP and JPN.", "IN is input/output; SUB is arithmetic; JMP is unconditional; JPN is conditional/compare."),
    q("Distinguish CMP #4 from CMI 40.", "CMP #4 compares ACC with immediate value 4; CMI 40 follows the address stored at memory location 40 and compares ACC with the indirectly addressed value."),
    q("What do MOV IX, STO TOTAL, OUT and END do?", "MOV IX copies ACC to IX; STO TOTAL stores ACC at the symbolic address TOTAL; OUT outputs the ASCII character whose code is in ACC; END returns control to the operating system."),
    q("Trace LDM #2; ADD #3; STO TOTAL. What changes?", "ACC becomes 2, then 5; memory at symbolic address TOTAL becomes 5.")
  ], "Trace the supplied program and classify the instructions, showing each change to ACC, IX, memory, output and control flow.", [["M1", "uses one row per executed instruction in the correct control-flow order"], ["A1", "updates ACC and IX correctly for data movement/arithmetic"], ["A1", "updates memory or output correctly for STO/OUT"], ["M1", "records compare result before evaluating JPE or JPN"], ["A1", "follows the correct taken/not-taken branch and skips non-executed lines"], ["B1", "classifies used instructions in the official data movement, input/output, arithmetic, unconditional/conditional and compare groups"]], "Do not accept relative LDR, immediate CMI, equality/zero JPE, negative JPN, or a trace that executes a line skipped by a taken branch."),

  r(47, ["S4.13", "S4.14"], "Addressing modes and address-sensitive instructions", [
    "Immediate addressing uses the operand as the value itself. Direct addressing uses the operand as the address of the value. Indirect addressing treats the operand as the address of a location that holds the effective address. Indexed addressing forms an effective address by adding IX to the address operand. Relative addressing forms a target/effective address by adding an offset to the current or next instruction address held in PC.",
    "LDI follows the address stored at the operand location; LDX adds IX to the address operand; LDR #n loads the immediate value n into IX. CMI <address> uses indirect addressing: the contents of <address> give the address of the value compared with ACC.",
    "After CMP or CMI, JPE <address> jumps when the comparison result is True and JPN <address> jumps when it is False. Relative addressing is a required addressing-mode concept, but LDR is not a relative-load instruction in the Version 2 instruction set."
  ], "Compare five operand interpretations", "With operand 20, immediate uses value 20; direct uses Memory[20]; indirect follows Memory[20] as another address; indexed uses address 20 + IX; relative uses PC plus a signed or stated offset. Separately, if CMI POINTER produces True, JPE MATCH branches to MATCH; a False comparison allows JPN DIFFERENT to branch.", [
    q("Which load follows a pointer in memory?", "LDI."),
    q("Which load combines its operand with IX?", "LDX."),
    q("What does LDR #4 do?", "It loads 4 into IX; it does not use relative addressing."),
    q("When does JPE branch?", "When the preceding comparison result is True."),
    q("How is a relative address formed?", "By adding an offset to the current or next instruction address represented by PC, according to the stated model.")
  ], "Distinguish immediate, direct, indirect, indexed and relative addressing, then state the effects of LDR #n, CMI <address>, JPE <address> and JPN <address>.", [["B1", "immediate uses operand as value; direct uses operand as address"], ["B1", "indirect follows an address stored at the operand address"], ["B1", "indexed adds IX to the address operand"], ["B1", "relative adds an offset to the PC/current or next instruction address"], ["B1", "LDR loads immediate n to IX and CMI compares through indirect addressing"], ["B1", "JPE follows True and JPN follows False"]], "Do not award relative LDR, immediate CMI, equal/zero JPE or negative-status JPN."),

  r(48, ["S4.08"], "Interrupt causes, detection and handling", [
    "An interrupt is a signal or condition requesting processor attention. Possible causes include input/output devices needing service, a timer used for scheduling, a hardware fault, and a software exception. Applications include responsive input, sharing processor time and dealing promptly with exceptional conditions without continuously polling every device.",
    "For most maskable interrupts, the processor completes the current instruction and checks for pending enabled interrupts at the end of that fetch-execute cycle, before beginning the next instruction. Detection is therefore not the same as stopping halfway through an ordinary instruction.",
    "If an interrupt is accepted, the processor checks priority, saves the state needed to resume (such as PC, registers and status), loads or locates the correct interrupt service routine (ISR), executes the ISR, restores the saved state and resumes the interrupted program at the correct next instruction. The ISR is a routine, not the interrupt signal itself."
  ], "Handle a keyboard interrupt", "A key press raises an interrupt while the CPU is executing another program. The CPU finishes its current instruction, detects the pending request at the cycle boundary, saves PC/register/status state, runs the keyboard ISR to read or acknowledge the input, restores the saved state and continues the original program.", [
    q("Give two possible causes or applications of interrupts.", "For example an I/O device request, timer/scheduler event, hardware fault or software exception."),
    q("When is a normal maskable interrupt detected and accepted?", "After the current instruction completes, at the end of the fetch-execute cycle before the next instruction begins, subject to enabled/priority checks."),
    q("What is an ISR?", "An interrupt service routine: program code that handles a particular interrupt."),
    q("Why must processor state be saved and restored?", "So the interrupted program can resume at the correct instruction with its earlier register and status values."),
    q("List the handling sequence after detection.", "Check/accept, save state, locate and execute ISR, restore state, resume program.")
  ], "Describe one interrupt cause or application, state when it is detected in the fetch-execute cycle, and trace handling through the ISR to resumption.", [["B1", "valid cause/application such as I/O, timer, fault or exception"], ["B1", "current instruction completes and interrupt is detected/checked at the cycle boundary"], ["B1", "priority/enabled status is checked"], ["B1", "PC/register/status state is saved"], ["B1", "correct ISR is located and executed"], ["B1", "state is restored and the interrupted program resumes"]], "Do not accept that every interrupt stops an instruction halfway through, that the ISR is the signal, or that the whole interrupted program restarts."),

  r(49, ["S4.05"], "Complete processor performance factors", [
    "Processor performance depends on processor type, number of cores, bus width, clock speed and cache memory. Processor type means the processor architecture and instruction-set design, including how much useful work its execution units can perform for a particular instruction or workload; a clock-rate comparison alone is therefore not sufficient.",
    "More cores can execute independent threads concurrently when software exposes parallel work. Wider data buses can transfer more bits per transfer, while address-bus width affects the address space. Higher clock speed provides more clock cycles per second, and cache reduces waiting when frequently used instructions or data are found close to the CPU.",
    "No factor guarantees that every program runs faster. Performance must be justified for the stated workload, because software parallelism, instruction-set compatibility, cache behaviour, memory traffic, heat and other bottlenecks can limit the benefit."
  ], "Compare two processors for two workloads", "Processor A has four faster general-purpose cores and a larger cache; Processor B has eight specialised cores but a lower clock speed. A lightly threaded office program may favour A's processor type, clock behaviour and cache, while a parallel workload written for B's processor type may use more cores. Bus width and memory traffic must also be considered before reaching a conclusion.", [
    q("What does processor type mean as a performance factor?", "The processor architecture/instruction-set and execution design, which determines what work it can perform per instruction or for a particular workload."),
    q("Why do more cores not always improve one program?", "The program must contain independent threads or tasks that can run in parallel."),
    q("How can bus width affect performance?", "A wider data bus can transfer more bits per transfer; address-bus width affects the address space rather than directly guaranteeing speed."),
    q("Why can cache improve performance?", "A cache hit supplies frequently used data or instructions faster than main memory, reducing CPU waiting.")
  ], "Two computers have different processor types. Explain how processor type, number of cores, bus width, clock speed and cache can affect their performance for a stated workload.", [["B1", "processor type linked to architecture/instruction-set/execution design and workload"], ["B1", "cores linked to available parallel threads/tasks"], ["B1", "bus width linked accurately to bits transferred or address space"], ["B1", "clock speed linked to cycles per second"], ["B1", "cache linked to reducing slower main-memory access"], ["B1", "conclusion recognises workload and bottlenecks rather than claiming one factor guarantees speed"]], "Do not accept processor type as only a brand name, or claim that the highest clock speed or largest core count always wins."),

  r(51, ["S4.13", "S4.15"], "Section 4 semantic checkpoint", [
    "Read each instruction by its specified effect: LDR #n loads the immediate value n into IX; CMI <address> compares ACC with a value reached by indirect addressing; JPE <address> jumps after a True comparison; JPN <address> jumps after a False comparison.",
    "For bit manipulation, identify the fixed width and bit numbering before tracing. AND tests or clears selected bits, OR sets selected bits, XOR toggles selected bits, and logical, arithmetic and cyclic shifts differ in fill and rotation behaviour."
  ], "Resolve four instruction cards", "Match LDR #4 to IX <- 4, trace CMI POINTER through the address stored at POINTER, send a True comparison to JPE MATCH and a False comparison to JPN DIFFERENT. None of the four names should be decoded by an English guess.", [
    q("What does LDR #6 change?", "It loads the immediate value 6 into IX."),
    q("How does CMI <address> obtain the comparison value?", "It uses indirect addressing: the operand location contains the address of the value compared with ACC."),
    q("Which branch follows a True comparison, and which follows a False comparison?", "JPE follows True; JPN follows False."),
    q("Which operation toggles selected device bits?", "XOR with a mask containing 1 at each bit to toggle.")
  ], "State the exact effects of LDR #n, CMI <address>, JPE <address> and JPN <address>.", [["B1", "LDR loads immediate n into IX"], ["B1", "CMI obtains the comparison value by indirect addressing"], ["B1", "CMI compares that value with ACC"], ["B1", "JPE branches after a True comparison"], ["B1", "JPN branches after a False comparison"]], "Do not infer an instruction effect from the mnemonic letters; use the specified instruction-set semantics."),

  r(53, ["S5.01"], "Why an operating system is required and what it manages", [
    "An operating system is required to provide a controlled interface between applications, users and hardware, and to coordinate shared resources. Without it, each application would need its own incompatible routines for processor time, memory, files, security and devices.",
    "Process management schedules CPU time and tracks running processes. Memory management allocates and protects RAM. File management organises files, folders, metadata and file operations. Security management authenticates users and enforces permissions or access rights.",
    "Hardware management coordinates devices through drivers, interrupts, buffers and queues. These roles cooperate: security management decides whether a request is authorised, while file or hardware management performs the permitted operation. Antivirus remains a utility and must not replace the OS security-management role."
  ], "Open a protected file and print it", "The OS authenticates the user and security management checks access rights. File management locates and opens the file; memory management allocates RAM; process management schedules the application; hardware management uses a printer driver, buffer and queue to send permitted output to the printer.", [
    q("Which OS role authenticates a user and enforces access rights?", "Security management."),
    q("Which role allocates RAM to a running process?", "Memory management."),
    q("Which role uses drivers, buffers and queues?", "Hardware management/device management."),
    q("Why is an operating system required?", "It provides a controlled interface and coordinates shared hardware and software resources for applications and users.")
  ], "Explain why an operating system is required and describe its process, memory, file, security and hardware management roles.", [["B1", "required interface/control layer between applications, users and hardware"], ["B1", "process management schedules CPU time or tracks processes"], ["B1", "memory management allocates/protects RAM"], ["B1", "file management organises stored files and operations"], ["B1", "security management authenticates users or enforces permissions/access rights"], ["B1", "hardware management uses drivers/interrupts/buffers/queues to coordinate devices"]], "Do not substitute antivirus utility software for OS security management, and do not treat stored files as RAM."),

  r(55, ["S5.02"], "Required utility software", [
    "A disk formatter prepares a storage medium with file-system structures. A virus checker scans for, quarantines and removes malware. A disk defragmenter rearranges fragmented file blocks on a magnetic disk; it is not a speed treatment for SSDs.",
    "A disk contents analysis/repair utility examines file-system structures, reports faults and attempts defined repairs. Compression reduces file size and backup creates a separate recoverable copy. Encryption may be useful additional protection, but it does not replace any of the six named syllabus utilities."
  ], "Choose the utility from the fault", "Use a formatter to prepare a new storage medium, disk analysis/repair for file-system errors, a backup to recover a deleted file, and compression to reduce transfer size. Choose by the operation required, not by calling every tool 'maintenance'.", [
    q("Which utility prepares file-system structures on a storage medium?", "A disk formatter."),
    q("Which utility checks file-system structures and attempts repairs?", "A disk contents analysis/repair utility."),
    q("Why is compression not a backup?", "Compression reduces size; a backup creates a separate copy that can be restored.")
  ], "A computer has a new storage medium and another disk reports file-system errors. Name the utility for each task and explain its purpose.", [["B1", "disk formatter for the new medium"], ["B1", "formatter creates/prepares file-system structures"], ["B1", "disk contents analysis/repair utility for the faulty disk"], ["B1", "it examines structures and reports/attempts repair of faults"]], "Do not accept defragmentation as formatting or as a general file-system repair operation."),

  r(56, ["S5.04", "S5.05"], "Assembler, compiler and interpreter choices", [
    "An assembler is needed to translate a processor-specific assembly-language program into machine code or object code. A compiler is needed to translate a whole high-level language program before execution, normally producing target/object code. An interpreter translates and executes a high-level language program statement by statement during execution, normally without producing a separate permanent object-code file.",
    "Compiler advantages include faster repeated execution after translation, distribution without the source code and translation checks across the whole program. Disadvantages include a separate compilation step and an error list that may need several corrections before execution. Interpreter advantages include immediate statement-level feedback and convenient incremental testing. Disadvantages include repeated translation overhead, slower execution and needing the interpreter and usually the source program at run time.",
    "A justified choice must connect the mechanism to the scenario: an interpreter can suit development and debugging; a compiler can suit repeated use or distribution; an assembler is required for assembly source. These are advantages and disadvantages of the translation approaches, not universal claims that one tool is always better."
  ], "Choose tools across development and deployment", "During development, an interpreter can execute each statement and stop near a fault, giving quick feedback. For final distribution, a compiler can translate the whole high-level program before execution and provide target/object or executable code without distributing the source. A processor-specific assembly routine requires an assembler because its mnemonic instructions must become the target processor's machine code.", [
    q("Why is an assembler needed?", "It translates assembly-language mnemonics and operands into machine or object code for the target processor."),
    q("Give one compiler advantage and its mechanism.", "A compiled program can run repeatedly without translating the source each time because translation occurred before execution."),
    q("Give one compiler disadvantage.", "Compilation must complete before execution and the programmer may need to correct a list of reported errors."),
    q("Give one interpreter advantage and one disadvantage.", "It provides immediate statement-level feedback, but repeated translation can make execution slower and requires the interpreter/source at run time."),
    q("Which translator is required for assembly language?", "An assembler.")
  ], "Compare a compiler and an interpreter using two advantages and two disadvantages, then justify the translator used for an assembly-language routine.", [["B1", "compiler translates the whole high-level program before execution and produces target/object code"], ["B1", "compiler advantage linked to repeated execution or distribution without source"], ["B1", "compiler disadvantage linked to separate translation or error-list workflow"], ["B1", "interpreter translates/executes statements during execution and gives immediate feedback"], ["B1", "interpreter disadvantage linked to repeated translation, slower execution or run-time dependency"], ["B1", "assembler selected and justified for assembly-language-to-machine/object-code translation"]], "Do not award vague claims such as 'compiler is faster' or 'interpreter is easier' without the mechanism and scenario."),

  r(58, ["S5.03"], "Libraries and dynamically linked library files", [
    "Software under development is often constructed using existing code from program libraries. A program library is a collection of reusable routines or modules, so a developer can call tested implementations instead of rewriting common mathematical, input/output, graphics or string operations.",
    "Benefits to the developer include shorter development time, less duplicated source code, reuse of tested routines and more consistent maintenance. A dynamically linked library (DLL) is connected when a program loads or calls it rather than copying all library code into every executable.",
    "DLL files can reduce executable size and memory duplication, support reuse and allow one shared update. They also create dependency and version risks: a missing or incompatible DLL can stop a program loading or change behaviour."
  ], "Three programs use one graphics DLL", "All three executables call the shared graphics code. One loaded copy may be shared in memory and a security fix can update the DLL once, but replacing it with an incompatible version can break all three programs.", [
    q("How do program libraries support software under development?", "They supply existing reusable routines or modules, avoiding the need to write common code again."),
    q("When is a dynamically linked library connected to a program?", "At load time or run time when required."),
    q("Give one storage benefit of dynamic linking.", "Library code need not be copied into every executable."),
    q("Give one DLL risk.", "A missing/incompatible version can prevent execution or cause faults.")
  ], "Explain two benefits and one drawback of using a dynamically linked library.", [["B1", "shared reusable code / avoids rewriting"], ["B1", "smaller executables or reduced duplicate memory/storage"], ["B1", "shared library can be updated once"], ["B1", "missing/incompatible DLL can stop or alter programs"]], "Do not accept 'saves space' unless duplication or executable size is explained."),

  r(59, ["S12.04"], "Expose, locate and correct program errors", [
    "A syntax error breaks the language grammar and is normally exposed by a translator or an IDE's dynamic syntax check. A logic error uses valid syntax but follows the wrong algorithm, so a trace, dry run, walkthrough or deliberately selected test can expose an unexpected result. A run-time error occurs during execution, such as division by zero or opening a missing file, so exception messages and run-time diagnostics help locate it.",
    "After an error is exposed, locate the responsible statement and identify the error type before changing it. Correct the cause, not only the observed output, then rerun the failing test and relevant regression tests. Avoid faults by using clear identifiers, modular design, validation, desk checking, peer walkthroughs and a planned set of normal, abnormal and extreme/boundary tests.",
    "No single method proves that a program has no remaining faults. Translation can expose syntax faults but not every logic fault; testing can reveal failures for selected cases but cannot demonstrate correctness for every possible input."
  ], "Correct three different faults", "A missing ENDIF is a syntax error exposed during translation and corrected by closing the selection. Mark > 50 for a pass boundary of 50 is a logic error exposed by tracing Mark = 50 and corrected to Mark >= 50. Total / Count when Count may be 0 is a run-time risk exposed during execution and avoided by testing Count before division.", [
    q("Which method can expose a syntactically valid wrong boundary?", "A trace, dry run, walkthrough or selected boundary test can expose the wrong result."),
    q("Why is a translator insufficient for all logic errors?", "Logic errors can obey the language grammar, so translation may succeed even though the result is wrong."),
    q("What must happen after a correction?", "Rerun the failing test and relevant regression tests to check the correction and existing behaviour.")
  ], "For each fault, state its type, one way to expose or locate it, and the correction: a missing ENDIF; IF Mark > 50 when 50 should pass; Average <- Total / Count when Count can be zero.", [["B1", "missing ENDIF identified as syntax error and translator/dynamic syntax check used"], ["A1", "adds the required ENDIF"], ["B1", "Mark > 50 identified as logic error and boundary trace/test at 50 used"], ["A1", "changes the condition to Mark >= 50 or equivalent"], ["B1", "division by zero identified as run-time error/risk and execution/test diagnostics used"], ["A1", "guards the division by checking Count or handles the zero case"]], "Do not accept changing the expected result to hide a program fault, or claim that successful translation proves the algorithm correct."),

  r(60, ["S5.06", "S5.07"], "Java translation and required IDE features", [
    "Java in console mode is partly compiled and partly interpreted: the Java compiler translates source code into platform-independent bytecode, then a Java Virtual Machine (JVM) interprets that bytecode and may just-in-time compile parts for the host processor. Bytecode is not universal processor machine code.",
    "For coding, an IDE can provide context-sensitive prompts. For initial error detection it can perform dynamic syntax checks. For presentation it can prettyprint code and expand or collapse code blocks. These features help create and navigate source code but do not prove that its algorithm is correct.",
    "For debugging, an IDE can provide single stepping, breakpoints, inspection of variables and expressions, and a report window for diagnostic or output information. Single stepping executes one statement at a time; a breakpoint pauses at a chosen point; variable/expression inspection exposes changing values."
  ], "Trace Java and locate a loop fault", "First the Java compiler produces bytecode; the JVM then interprets the bytecode or JIT-compiles parts for the host. In the IDE, a breakpoint pauses before the faulty loop, single stepping advances one statement at a time, the variable/expression view exposes Index, and the report window records diagnostics. Dynamic syntax checking can flag malformed syntax but not a syntactically valid wrong boundary.", [
    q("What does a Java compiler normally produce?", "Bytecode."),
    q("Why is Java described as partly compiled and partly interpreted?", "Source is compiled to bytecode, then a JVM interprets the bytecode and may JIT-compile parts for the host."),
    q("Which IDE feature pauses at a chosen line, and which advances one statement?", "A breakpoint pauses; single stepping advances one statement at a time."),
    q("Name the two required presentation features.", "Prettyprint and expand/collapse code blocks."),
    q("What can a variables/expressions view and report window show?", "Current or evaluated values, plus diagnostic/output information in the report window.")
  ], "Explain why Java is partly compiled and partly interpreted, then describe four IDE features from coding, initial error detection, presentation and debugging.", [["B1", "Java source is compiled to bytecode"], ["B1", "JVM interprets bytecode and may JIT-compile parts for the host"], ["B1", "context-sensitive prompts or dynamic syntax checking described accurately"], ["B1", "prettyprint or expand/collapse code blocks described accurately"], ["B1", "single stepping or breakpoint described accurately"], ["B1", "variable/expression inspection or report window described accurately"]], "Do not accept that Java source becomes one universal machine-code file or that IDE syntax checking proves logical correctness."),

  r(62, ["S6.01", "S6.02"], "Security, privacy and data integrity", [
    "Data security is protection against unauthorised access, loss or damage. Privacy concerns appropriate collection, use and disclosure of personal data. Integrity means data remains accurate, complete and unaltered except by authorised processes.",
    "The concepts overlap but are not synonyms: encrypted inaccurate data may be secure but lack integrity; authorised publication may preserve integrity while violating privacy.",
    "Both data security and computer-system security are necessary. Protecting only a data file is insufficient if an attacker can control the operating system, install malware, steal credentials or make the computer system unavailable; protecting only the device is insufficient if copied data is disclosed, altered or lost."
  ], "Medical records on a compromised computer system", "Encryption restricts unauthorised reading of the record data. Access rights restrict who may view or alter it. Anti-virus and a firewall help protect the computer system that stores and processes the records. If malware controls the system, it may steal decrypted data, alter records or stop authorised access even though the stored file was encrypted.", [
    q("Which concept is damaged when data is altered incorrectly?", "Integrity."),
    q("Which concept concerns how personal data is collected and disclosed?", "Privacy."),
    q("Can data be secure but inaccurate?", "Yes; access protection does not guarantee correctness."),
    q("Why must the computer system also be protected?", "A compromised or unavailable system can expose, alter, delete or prevent access to the data it processes, even when a stored file has a separate protection such as encryption.")
  ], "Distinguish data security, privacy and integrity, then explain why both data and its computer system require security.", [["B1", "security protects against unauthorised access/loss/damage"], ["B1", "privacy controls appropriate personal-data use/disclosure"], ["B1", "integrity concerns accuracy/completeness/authorised change"], ["B1", "computer-system compromise can expose/alter/destroy data or prevent authorised access"], ["B1", "data-specific and system controls are both required / one does not replace the other"]], "Do not accept repeated versions of 'keeping data safe' or the claim that file encryption alone secures the computer system."),

  r(63, ["S6.03", "S6.04"], "Virus, spyware, anti-virus and anti-spyware", [
    "A virus is malware that attaches to a host file or program and spreads when the infected host is run or shared. Spyware secretly monitors activity or collects data, such as keystrokes, credentials or browsing behaviour. These threats can damage the security of both data and the computer system.",
    "Anti-virus software scans files, memory and activity for virus signatures or suspicious behaviour, then blocks, quarantines or removes detected malicious code. Anti-spyware performs corresponding detection and removal for spyware; the categories may be combined in one security product, but their syllabus roles must still be stated accurately.",
    "Anti-virus and anti-spyware definitions and detection rules must be updated because new threats appear. Both measures reduce risk but cannot guarantee detection of every new, modified or concealed threat."
  ], "Infected attachment and keylogger", "Anti-virus scans an attachment, matches a virus signature and quarantines the infected host file before it runs. Anti-spyware detects a keylogger process, blocks it and quarantines its file so it cannot continue recording credentials. Each control is matched to the threat mechanism rather than described as a universal guarantee.", [
    q("How does a virus differ from spyware?", "A virus attaches to a host and spreads when that host runs or is shared; spyware secretly monitors activity or collects data."),
    q("What is the role of anti-virus software?", "It scans for virus signatures or suspicious behaviour and can block, quarantine or remove detected malicious code."),
    q("What is spyware designed to do?", "Secretly monitor activity or collect user/system data."),
    q("What does quarantine do?", "Isolates suspicious code so it cannot execute normally."),
    q("Why update anti-spyware definitions?", "To recognise newly identified spyware.")
  ], "Explain how anti-virus and anti-spyware software reduce different malware risks.", [["B1", "anti-virus scans for virus signatures/suspicious behaviour"], ["B1", "blocks/quarantines/removes detected infected code"], ["B1", "anti-spyware scans for secret monitoring/data collection"], ["B1", "blocks/quarantines/removes detected spyware"], ["B1", "updates improve recognition of newly identified threats"], ["B1", "neither measure guarantees detection of every threat"]], "Do not accept that virus and spyware are synonyms, or that either security measure prevents every form of malware."),

  r(64, ["S6.04", "S6.05"], "Required internet threats and matching risk-reduction methods", [
    "The required threats are malware (virus and spyware), hackers, phishing and pharming. A hacker gains unauthorised access to a computer system or data. Phishing uses a deceptive message, link or site to persuade a user to disclose information. Pharming redirects traffic to a fake website, possibly even after the user enters the correct address.",
    "Methods restrict risk only when their mechanism matches the threat: updated anti-virus and anti-spyware can detect known malware; user training and independent contact checks reduce phishing; secure DNS, certificate/HTTPS checks and patched software reduce pharming risk; strong authentication, access rights, patching, firewalls and monitoring reduce unauthorised access by hackers.",
    "A control reduces likelihood or impact; it rarely makes an attack impossible. Layered controls are needed because people, software, credentials and network traffic provide different attack routes."
  ], "Protect an online payroll service", "Staff receive a phishing email while a hacker probes the server and pharming redirects one user towards a fake site. Training and an independent sender check reduce phishing risk; multi-factor authentication reduces the value of a stolen password; a firewall filters unwanted traffic; access rights limit what an authenticated account may change; updated anti-virus and anti-spyware detect known virus or spyware signatures; secure DNS and certificate warnings reduce pharming risk.", [
    q("Distinguish phishing from pharming.", "Phishing persuades through a deceptive message/link/site; pharming redirects traffic to a fake site, potentially after the correct address is entered."),
    q("What is the syllabus meaning of a hacker threat?", "A person gaining or attempting unauthorised access to a computer system or data."),
    q("Match virus, spyware, phishing and pharming to one suitable risk-reduction method each.", "Updated anti-virus; updated anti-spyware; training/independent verification; secure DNS plus certificate/HTTPS checks, respectively."),
    q("Why are layered controls required?", "Different controls address different attack routes, so failure or bypass of one control need not expose the whole system.")
  ], "For each of virus, spyware, hacking, phishing and pharming, describe the threat route and one matching method that restricts its risk.", [["B1", "virus route plus anti-virus mechanism"], ["B1", "spyware route plus anti-spyware mechanism"], ["B1", "hacker/unauthorised-access route plus a matching access/network control"], ["B1", "phishing/deception route plus training or independent verification"], ["B1", "pharming/redirection route plus secure DNS/certificate/HTTPS or patched-software control"], ["B1", "states that controls reduce rather than eliminate risk"]], "Do not define phishing and pharming identically or award a control that is unrelated to the stated attack route."),

  r(65, ["S6.03"], "User accounts, passwords and biometric authentication", [
    "A user account gives an individual or role a distinct system identity and supports accountability. A password is secret knowledge used to authenticate an identity claim. Accounts should not be shared; passwords should be difficult to guess, stored as salted hashes, protected by attempt limits and changed if compromised.",
    "Biometrics use a physical or behavioural characteristic such as fingerprint, face, iris, retina, voice or typing pattern. A captured feature is converted to a template and compared with an enrolled template. A match authenticates the identity claim; authorisation is the separate decision about what that user may access or do.",
    "False rejection denies a valid enrolled user by mistake; false acceptance authenticates an impostor by mistake. Biometrics can be convenient and cannot be casually shared like a password, but require sensors/templates, may raise privacy concerns and cannot normally be replaced as easily as a compromised password."
  ], "Account login with fingerprint", "A named staff account first supplies a password, then a fingerprint sensor captures a feature and compares its template with the enrolled template. A match authenticates the claimed identity. The access-rights system then separately decides whether that account may read payroll data; the biometric match itself does not grant every permission.", [
    q("What is the purpose of a user account?", "It provides a distinct identity for authentication, access control and accountability."),
    q("What does a biometric match establish?", "It provides evidence that the presented feature matches the enrolled identity template; it authenticates the identity claim."),
    q("Does successful authentication decide every permitted action?", "No. Authorisation/access rights separately decide what the authenticated user may access or do."),
    q("Distinguish false accept from false reject.", "False accept authenticates an impostor; false reject denies a valid enrolled user.")
  ], "Describe how user accounts, passwords and biometrics can protect a computer system, including one limitation of each authentication method.", [["B1", "account supplies a distinct identity/accountability record"], ["B1", "password is secret knowledge checked during authentication"], ["B1", "password limitation such as guessing/phishing/reuse/sharing"], ["B1", "biometric feature is captured and compared with an enrolled template"], ["B1", "biometric limitation such as false accept/reject, sensor/template or privacy risk"], ["B1", "authentication is distinguished from later authorisation/access rights"]], "Do not describe a biometric match as permission to access every resource or claim that biometrics cannot produce errors."),

  r(66, ["S6.05", "S6.06"], "Access rights and encryption as data-security methods", [
    "Access rights restrict authorised actions on resources. Read permission controls viewing; write/modify controls alteration; delete controls removal; execute or administrative rights control running software or changing system settings. Least privilege grants only the permissions needed for a role and removes temporary rights when no longer required.",
    "Encryption transforms plaintext into ciphertext using an algorithm and key. Without the correct decryption key, intercepted or stolen ciphertext should not reveal readable content. Encryption therefore protects confidentiality, while access rights can protect confidentiality and integrity by preventing unauthorised viewing or alteration.",
    "The methods do different jobs: encryption does not decide which logged-in user may edit a record, and access rights do not make a stolen unencrypted copy unreadable. Neither method guarantees availability, data truth or protection after an authorised account is misused."
  ], "Protect a payroll file", "The payroll file is encrypted at rest so a stolen storage device does not reveal readable salaries without the key. The payroll application grants read/write rights only to payroll staff and read-only rights to an auditor. A compromised ordinary account cannot open the file through the application, while an attacker who steals only the encrypted file still lacks readable plaintext.", [
    q("How do access rights protect confidentiality?", "They prevent users without read permission from viewing the data."),
    q("How do access rights protect integrity?", "They prevent users without write/delete permission from altering or removing the data."),
    q("How does encryption protect data?", "It converts plaintext to ciphertext that is unreadable without the correct key."),
    q("Why are both methods useful?", "Access rights govern permitted actions in the system; encryption protects the content of an intercepted or stolen copy.")
  ], "Explain how access rights and encryption protect a payroll file, and state one limitation of each method.", [["B1", "access rights restrict viewing to users/roles with read permission"], ["B1", "access rights restrict modification/deletion to permitted users/roles"], ["B1", "encryption converts plaintext to ciphertext using a key"], ["B1", "without the correct key the stolen/intercepted data is not readable"], ["B1", "access-rights limitation developed"], ["B1", "encryption limitation developed"]], "Do not claim that access rights detect changes, that encryption guarantees integrity, or that either method replaces the other."),

  r(67, ["S6.03", "S6.06"], "Digital signatures and encryption", [
    "A sender hashes the message and encrypts the hash with the sender's private key to form a digital signature. The receiver uses the sender's public key to recover/verify the signed hash and independently hashes the received message.",
    "Matching hashes provide evidence of integrity and origin/authenticity; a valid signature does not keep the message confidential. Certificates help bind a public key to an identity.",
    "Encryption is a separate security measure: it transforms readable plaintext into ciphertext and requires the correct key for decryption. A message may be signed for integrity/authenticity, encrypted for confidentiality, or both; neither mechanism should be credited for a property it does not provide."
  ], "Verify and protect a signed update", "The publisher signs a hash of the update with its private key. The device uses the publisher's public key, independently hashes the received update and compares the values; a mismatch rejects the update. If the update must also remain confidential in transit, it is separately encrypted for an authorised recipient.", [
    q("Which key creates a sender's digital signature?", "The sender's private key."),
    q("What does the receiver compare?", "The verified signed hash with a newly calculated message hash."),
    q("Does a digital signature encrypt the whole message for confidentiality?", "No. The content requires separate encryption if confidentiality is needed."),
    q("What property does message encryption provide?", "Confidentiality: ciphertext should be unreadable without the correct key.")
  ], "Describe how a digital signature is created and checked, then explain why separate encryption may also be required.", [["B1", "sender creates a hash of the message"], ["B1", "hash is signed/encrypted using sender's private key"], ["B1", "receiver uses sender's public key and hashes received message"], ["B1", "matching hashes provide integrity and sender-authenticity evidence"], ["B1", "separate encryption converts message plaintext to ciphertext"], ["B1", "confidentiality requires the correct decryption key"]], "Do not award confidentiality as the purpose of a signature or integrity/authenticity as an automatic result of encryption alone."),

  r(68, ["S6.03", "S6.05"], "Firewall protection from a stand-alone PC to a network", [
    "A firewall filters traffic entering or leaving a computer or network by comparing packet or connection information with configured rules. Rules may use source/destination address, port, protocol or connection state and then allow, block, reject or log the traffic.",
    "A host firewall can protect a stand-alone PC; a network firewall can protect a boundary between networks. This satisfies different scales of computer-system protection, but neither placement makes a firewall an anti-virus scanner or guarantees that allowed traffic is harmless.",
    "Firewalls restrict risk from unwanted connections and some unauthorised-access routes. They should be combined with accounts/passwords, authentication, access rights, anti-virus, anti-spyware, encryption, patching, user training and monitoring because those controls address different threats."
  ], "Protect a home laptop and a school network", "The laptop's host firewall blocks unsolicited inbound connections except an explicitly required service. The school's boundary firewall denies unrequested external traffic, permits web traffic under ordered rules and logs repeated blocked attempts. Anti-virus still scans downloaded files, and account/access controls still decide who may use data after traffic is allowed.", [
    q("What information may a firewall rule inspect?", "Source/destination address, port, protocol or connection state."),
    q("Distinguish a host firewall from a network firewall.", "A host firewall runs on and protects one computer; a network firewall filters traffic at a boundary for multiple connected systems."),
    q("Can a firewall replace anti-virus software?", "No. A firewall controls traffic; anti-virus scans for detected malicious code."),
    q("Why may allowed traffic still be dangerous?", "A permitted connection can carry phishing content, stolen credentials or malware that the rule does not recognise.")
  ], "Describe how a firewall can protect both a stand-alone PC and a network, then explain two limitations that require other security measures.", [["B1", "firewall compares traffic/connection information with configured rules"], ["B1", "allows/blocks/rejects/logs according to a rule"], ["B1", "host firewall protects one PC"], ["B1", "network firewall protects a network boundary"], ["B1", "allowed traffic or misconfiguration limitation"], ["B1", "matching additional measure such as anti-virus, authentication, access rights or user training"]], "Do not claim that a firewall removes viruses, detects every malicious payload or makes a computer system completely secure."),

  r(69, ["S6.07", "S6.08"], "Complete validation and verification methods", [
    "Validation checks whether data is reasonable and follows rules: range, format, length, presence, existence, limit and check digit. It cannot prove truth. A range check applies both a lower and an upper bound, such as 0 to 75. A limit check applies one stated upper or lower limit, such as file size no greater than 10 MiB or temperature at least -20 degrees Celsius.",
    "A format check tests a required pattern; a length check tests the number of characters; a presence check rejects a blank required field; an existence check confirms a value is stored in a specified lookup file; and a check digit is calculated from the other digits and compared. Verification checks whether data was copied accurately, using visual checking or double entry.",
    "Error detection includes parity: a parity byte checks one group and block parity adds row/column checks; a checksum is calculated from a data block and compared after transmission. These detect many errors but do not correct every error."
  ], "Validate input, then verify a transferred record", "A 10 MiB maximum uses an upper limit check because it has one permitted limit; a mark from 0 to 75 uses a range check because it has both lower and upper bounds. A product code uses presence, length, format, existence and check-digit rules. During entry, visual checking or double entry compares values. During transfer, byte parity detects many single-bit errors, block parity adds row/column evidence and a checksum is recalculated from the received data block.", [
    q("Which check enforces a file size of no more than 10 MiB?", "An upper limit check."),
    q("How does a range check differ from a limit check?", "A range check applies both lower and upper bounds; a limit check applies one stated upper or lower limit."),
    q("Which check confirms a foreign code is already stored in a lookup file?", "Existence check."),
    q("Match each rule to its validation check: AA1234 follows two letters then four digits; a code has exactly six characters; a required name is not blank; a barcode includes a digit calculated from the other digits.", "Format check; length check; presence check; check digit, respectively."),
    q("How does double-entry verification work?", "Data is entered twice and the two entries are compared."),
    q("Distinguish byte parity from block parity.", "Byte parity checks the agreed odd/even parity for one byte; block parity applies parity across rows and columns of a block and can locate many single-bit errors."),
    q("What happens to a checksum at the receiver?", "It is recalculated and compared with the transmitted checksum.")
  ], "Describe one verification method used during data entry and two methods used during data transfer.", [["B1", "visual check against source or double entry with comparison"], ["B1", "byte parity uses an agreed odd/even parity bit and checks it at the receiver"], ["B1", "block parity checks rows and columns / can locate many single-bit errors"], ["B1", "checksum is recalculated from received block and compared"], ["B1", "methods detect many errors but do not prove truth or automatically correct every error"]], "Do not substitute validation checks for verification, merge byte and block parity into one unexplained word, or claim that detection automatically corrects an error."),

  r(72, ["S7.01", "S7.02", "S7.03"], "Professional ethics, professional bodies and ethical decisions", [
    "Professional ethics provides principles for deciding how a computing professional should act when technical choices can affect clients, users, colleagues or wider society. Its purpose is to protect the public interest, support competent and honest work, and make professionals accountable for foreseeable consequences rather than treating legal compliance or a manager's instruction as the whole decision.",
    "Joining a professional ethical body is important because membership gives a practitioner an explicit code of conduct, current professional guidance, continuing professional development and a community through which standards and misconduct can be challenged. The British Computer Society (BCS) and the Institute of Electrical and Electronics Engineers (IEEE) are the two named syllabus examples. Their codes promote public interest, competence, integrity, privacy and accountability; a code guides judgement but does not replace law.",
    "For a given situation, decide whether an action is ethical or unethical by identifying the decision, affected stakeholders, benefits, harms, rights and responsibilities. Then explain the impact of acting ethically and the impact of acting unethically. A defensible conclusion applies evidence, proportionality and safeguards; it is not a one-sided list or an unsupported personal opinion."
  ], "Unsafe release pressure", "A developer is told to hide failed safety tests so a medical system can launch on time. Concealing the evidence would be unethical because patients could be harmed and trust would be damaged. The developer acts ethically by documenting the risk, refusing to falsify the record and escalating through BCS/IEEE-style professional channels. This may delay release and cost money, but protects patients, supports accountability and allows the defect to be corrected.", [
    q("What is the purpose of professional ethics in computing?", "To guide competent, responsible and accountable decisions that protect clients, users and the public interest."),
    q("Why is joining a professional body such as BCS or IEEE important?", "It provides a code of conduct, professional guidance and development, accountability and a community that supports consistent standards."),
    q("In the unsafe-release situation, is concealing failed tests ethical or unethical?", "Unethical, because it hides foreseeable risk and can harm patients and public trust."),
    q("State one impact of acting ethically and one impact of acting unethically in that situation.", "Ethical escalation may delay release but protects patients and supports correction; concealment may meet the deadline but risks harm, liability and loss of trust.")
  ], "A software engineer is asked to deploy a safety-critical update despite unresolved test failures. Determine whether complying silently would be ethical or unethical, explain two stakeholder impacts, and explain how membership of BCS or IEEE could support the engineer's response.", [["B1", "identifies silent deployment/concealment as unethical with a reason"], ["B1", "explains one impact on users or the public"], ["B1", "explains one impact on the organisation or professional"], ["B1", "explains that a BCS/IEEE code supplies professional standards or public-interest duties"], ["B1", "explains that professional membership supplies guidance, development, accountability or an escalation community"], ["B1", "gives a justified ethical action such as document, refuse concealment, escalate or delay release"]], "Do not award a label such as 'unethical' without impact, or claim that joining a body removes the need for evidence and professional judgement."),

  r(74, ["S7.04", "S7.05"], "Copyright legislation, FSF, OSI and licence permissions", [
    "Copyright legislation is needed because software can be copied and distributed at very low cost while its creation requires time, skill and investment. It gives the copyright holder legal control over protected expression such as source code and documentation, including copying, distribution and adaptation, so unauthorised use can be challenged and creators can license work and receive revenue. Copyright protects expression rather than every abstract idea, and a limited legal exception is not permission for unrestricted copying.",
    "A software licence is the copyright holder's permission to use protected work under stated conditions; paying for or downloading software does not normally transfer ownership. The licence may allow or restrict installation, copying, modification and redistribution. Copyright legislation establishes the rights, while the licence defines which of those acts the user is permitted to perform.",
    "The Free Software Foundation (FSF) emphasises freedoms to run, study, modify and share software; source access is necessary for study and modification. The Open Source Initiative (OSI) defines open-source criteria and approves licences that meet them. Free/open-source software can still be sold and remains protected by copyright; users must follow conditions such as preserving notices, attribution or sharing derivative source under compatible terms."
  ], "Modify and redistribute a library", "A developer finds source code in a public repository. Copyright still protects the code, so visibility alone is not permission. An OSI-approved licence may allow modification and redistribution, while an FSF-aligned copyleft licence may require a distributed derivative to preserve notices and use compatible terms. The developer must check and follow the exact licence before copying the library into a product.", [
    q("Why is copyright legislation needed for software?", "It gives creators enforceable control over copying, distribution and adaptation, supporting permission, revenue and investment despite easy digital copying."),
    q("How does a licence differ from copyright ownership?", "Copyright establishes the owner's rights; a licence grants a user specified permissions without normally transferring ownership."),
    q("Which organisation emphasises the freedoms to run, study, modify and share software?", "Free Software Foundation (FSF)."),
    q("What is the role of the OSI?", "It defines open-source criteria and approves licences that meet them."),
    q("Can open-source software be sold or remain copyrighted?", "Yes. Open source concerns licence permissions and conditions, not zero price or absence of copyright.")
  ], "Explain why copyright legislation is needed for software and how an FSF- or OSI-aligned licence changes what a user may do with protected source code.", [["B1", "software is easy to copy/distribute while creation requires skill, time or investment"], ["B1", "copyright gives the holder control over protected expression and restricted acts"], ["B1", "licence grants specified permissions without normally transferring ownership"], ["B1", "FSF freedom or OSI licence-approval role is stated accurately"], ["B1", "source inspection/modification/redistribution permission is linked to the licence"], ["B1", "licence conditions such as notices, attribution or compatible redistribution terms remain binding"]], "Do not accept that copyright protects every idea, that a paid download transfers copyright, or that open source means public domain."),

  r(75, ["S7.05"], "Shareware and commercial licences", [
    "Shareware is distributed for trial or limited use, with payment commonly required for continued, full or unrestricted use. A commercial/proprietary licence grants defined use while normally restricting copying, modification and redistribution.",
    "Licence choice must fit the scenario: budget, support, source modification, redistribution, trial period, compatibility and legal obligations are relevant. 'Free to download' does not mean public domain."
  ], "Trial accounting package", "A company tests a limited shareware edition for 30 days, then buys commercial licences for continued use, vendor support and full reporting features.", [
    q("What commonly changes after a shareware trial?", "Payment is required or features/time become restricted."),
    q("Can a buyer normally redistribute unlimited copies of commercial software?", "No, unless the licence explicitly permits it."),
    q("Give one reason to choose a commercial licence.", "Vendor support, warranty, specialist features or compatibility, developed for the scenario.")
  ], "A school needs supported examination software but cannot modify or redistribute it. Justify a commercial licence and state one restriction.", [["B1", "vendor support/updates appropriate to examination use"], ["B1", "reliability/compatibility/accountability developed"], ["B1", "use limited to licensed users/devices"], ["B1", "copying/modification/redistribution restricted"]], "Do not award 'commercial is better' without a scenario-linked reason."),

  r(76, ["S7.06"], "AI applications and impact chains", [
    "AI applications include medical image classification, recommendation, fraud detection, language processing, autonomous control and predictive maintenance. A valid impact answer names the AI decision mechanism and traces a consequence for a stakeholder.",
    "Social impacts include access, bias and privacy; economic impacts include productivity, job redesign and error cost; environmental impacts include data-centre energy/material use and optimisation of transport or power. Evaluation balances benefits, harms and mitigations in context."
  ], "Medical triage model", "The model prioritises scans, reducing waiting time, but biased training data may miss a patient group. Human review, representative validation data and monitoring can reduce rather than eliminate the risk.", [
    q("Give one economic benefit of predictive maintenance.", "Reduced downtime or repair cost by predicting failure."),
    q("Give one environmental cost of training a large model.", "Electricity use and associated emissions/resource demand."),
    q("Why can biased training data create social harm?", "The model may produce systematically poorer decisions for under-represented groups.")
  ], "Evaluate the use of AI to select applicants for jobs.", [["B1", "valid benefit such as speed/consistent initial processing"], ["B1", "valid risk such as bias, opacity, privacy or exclusion"], ["B1", "explains a stakeholder consequence"], ["B1", "balanced judgement or mitigation linked to the context"]], "Do not accept a list of generic advantages/disadvantages without linking AI decisions to consequences."),

  r(77, ["S7.01", "S7.02", "S7.03", "S7.04", "S7.05", "S7.06"], "Section 7 required-content checkpoint", [
    "Professional ethics has a purpose: computing professionals must protect public interest, work competently and remain accountable for consequences. Joining a professional ethical body such as the British Computer Society (BCS) or the Institute of Electrical and Electronics Engineers (IEEE) provides codes of conduct, guidance, continuing professional development and a community that supports standards. In a situation, judge whether action is ethical or unethical and explain stakeholder impacts of both choices.",
    "Copyright legislation is needed to give creators enforceable control over software expression that can otherwise be copied and distributed cheaply. A licence grants permission without normally transferring ownership. The required licence categories are the Free Software Foundation (FSF), Open Source Initiative (OSI), shareware and commercial software; justify a choice from the scenario's permissions, restrictions, support, cost and redistribution needs.",
    "Artificial intelligence (AI) applications include classification, recommendation, prediction and autonomous control. Every AI evaluation should identify the application or decision mechanism and trace social, economic and environmental impacts before reaching a contextual judgement with realistic mitigations."
  ], "AI recruitment review", "An AI recruitment system may speed initial screening and reduce administrative cost, but biased data can unfairly exclude applicants, automated rejection can remove accountability, and model operation consumes computing resources. Human review, representative data, appeal, data minimisation and efficient infrastructure address different harms. The system is justified only if measured benefits outweigh social, economic and environmental costs under those safeguards.", [
    q("Name the two professional ethical bodies required in Section 7.", "British Computer Society (BCS) and Institute of Electrical and Electronics Engineers (IEEE)."),
    q("Name all four required software-licensing examples.", "Free Software Foundation (FSF), Open Source Initiative (OSI), shareware and commercial software."),
    q("Why is copyright legislation needed for software?", "It gives creators enforceable control over copying, distribution and adaptation of protected expression, supporting permission, revenue and investment."),
    q("Which three impact dimensions must an AI evaluation cover?", "Social, economic and environmental impacts."),
    q("What must follow an ethical or unethical label?", "An explanation of stakeholder consequences, evidence and a justified action or safeguard.")
  ], "A company proposes AI facial recognition for employee attendance. Evaluate the proposal using professional ethics and social, economic and environmental impacts.", [["B1", "identifies the AI biometric-matching application or mechanism"], ["B1", "explains a social benefit or harm for employees or the company"], ["B1", "explains an economic benefit or cost"], ["B1", "explains an environmental benefit or computing/resource cost"], ["B1", "applies professional-ethics duties such as public interest, privacy, competence or accountability"], ["B1", "explains a matching safeguard such as human review, appeal, access/retention limits or monitoring"], ["B1", "considers an alternative such as cards or manual attendance"], ["B1", "reaches a conditional judgement using named benefits, harms and safeguards"]], "Do not accept a topic-name list, a one-sided AI claim, or BCS/IEEE as unexplained initials."),

  r(78, ["S8.01", "S8.05", "S8.06"], "DBMS features and practical software tools", [
    "A file-based approach can repeat facts in separate files, create inconsistent copies and isolate related data. A Database Management System (DBMS) addresses these file-based limitations by providing data management, including a data dictionary of metadata; data modelling; a logical schema; data integrity; and data security. Security includes backup procedures and access rights assigned to individual users or groups.",
    "A developer interface provides tools used to define structures and build database applications, forms or reports. A query processor interprets and checks a query, chooses how to carry it out, accesses the stored data and returns or modifies the specified records while the DBMS applies access and integrity rules."
  ], "Run a restricted query", "A developer enters a SELECT statement through the developer interface. The query processor checks the statement and the user's access rights, works out an execution plan, retrieves the permitted rows and returns the result. The data dictionary supplies definitions such as field types, keys and constraints; it does not hold the ordinary user records.", [
    q("What five broad DBMS feature areas are required?", "Data management including a data dictionary, data modelling, logical schema, data integrity, and data security including backup and access rights."),
    q("What does a data dictionary store?", "Metadata such as table, field, type, key and constraint definitions."),
    q("What is the purpose of a developer interface?", "To provide tools for defining structures or building database applications, forms and reports."),
    q("What is the role of the query processor?", "To interpret/check, plan and carry out database queries or data-maintenance statements."),
    q("Which DBMS feature limits users or groups to permitted operations?", "Access rights within data security.")
  ], "A school is introducing a relational DBMS. Explain four DBMS features and the distinct purposes of the developer interface and query processor.", [["B1", "data management/data dictionary stores metadata about structure"], ["B1", "data modelling or logical schema represents the database design"], ["B1", "integrity rules maintain valid and consistent data"], ["B1", "security uses access rights and backup procedures"], ["B1", "developer interface supports defining structures or building database applications/forms/reports"], ["B1", "query processor interprets/checks and carries out queries or maintenance statements"]], "Do not treat the database, data dictionary, developer interface and query processor as interchangeable names."),

  r(79, ["S8.01"], "File-based limitations and relational solutions", [
    "A file-based approach stores data in separate application files. The same fact may be repeated in several files or records, causing redundancy and wasted storage. Updating only some copies creates inconsistency; insertion and deletion can also lose or require unrelated facts. Separate files may use incompatible formats, isolate data, duplicate validation/security code and make shared querying, concurrent access, backup and recovery harder to manage.",
    "A relational database addresses these limitations by separating entities into linked tables, storing shared facts once, identifying records with keys and enforcing relationships and constraints centrally. A DBMS supplies shared query processing, integrity, security, access rights and backup. These mechanisms reduce particular file-based risks; a relational design is not automatically smaller, simpler or error-free."
  ], "Replace a repeated order file", "A flat Order file repeats CustomerName and Address in every order row. Split it into Customer(CustomerID, CustomerName, Address) and Order(OrderID, CustomerID, OrderDate). CustomerID links each order to one stored customer, so an address is updated once instead of in every order row.", [
    q("Why can repeated data create inconsistency?", "One copy may be changed while another remains out of date."),
    q("What is data isolation in a file-based system?", "Related data is kept in separate files or formats, making combined access and queries difficult."),
    q("Which relational feature connects an order to its customer?", "A foreign key in Order referring to the Customer primary key."),
    q("Why is 'relational databases are always simpler' not a valid benefit?", "Linked tables and DBMS administration add complexity; benefits must be tied to a file-based limitation.")
  ], "A clinic repeats patient details in separate appointment, billing and treatment files. Explain three file-based limitations and a relational-database feature that addresses each one.", [["B1", "repeated patient facts cause redundancy or wasted storage"], ["B1", "linked tables store a shared patient fact once"], ["B1", "separate copies can become inconsistent after partial updates"], ["B1", "central keys/constraints and one stored fact improve consistency"], ["B1", "isolated files/formats make combined retrieval or control difficult"], ["B1", "DBMS query, integrity, access-right or backup service addresses the named difficulty"]], "Do not award a generic claim such as 'relational is better' without a named limitation, mechanism and consequence."),

  r(80, ["S8.02"], "Relational terminology, keys and indexing", [
    "An entity is a real-world thing about which data is stored and is commonly represented by a table. A table contains records (tuples); each record describes one entity occurrence. A field (attribute) is one named property or column. These paired terms are related but should not be collapsed into one definition.",
    "A candidate key is a minimal field or field set that uniquely identifies a record. One candidate key is selected as the primary key. A secondary key is a field used as an additional retrieval or ordering route and need not be unique; it is not another name for an unselected candidate key. A foreign key refers to a key in a related table. An index is a lookup structure built on one or more fields: it can speed retrieval but uses storage and must be maintained after changes."
  ], "Keys for a student table", "In Student(StudentID, Email, TutorGroup), StudentID and Email may be candidate keys if both are unique and minimal; StudentID is selected as primary. TutorGroup can be a secondary key for retrieving all students in one group even though many records share the value. An index on TutorGroup can provide a faster lookup route.", [
    q("Distinguish a record/tuple from a field/attribute.", "A record/tuple is one complete row for an entity occurrence; a field/attribute is one named property or column."),
    q("What makes a candidate key minimal?", "No field can be removed while retaining uniqueness."),
    q("Must a secondary key uniquely identify one record?", "No. It may retrieve a set of records sharing the same value."),
    q("Give one benefit and one cost of an index.", "It can speed lookup/ordering, but uses storage and must be updated when data changes.")
  ], "For Student(StudentID, Email, TutorGroup), explain the roles of a candidate key, primary key, secondary key and index.", [["B1", "candidate key is a minimal unique identifier, such as StudentID or unique Email"], ["B1", "primary key is the candidate selected to identify each record"], ["B1", "secondary key is an additional retrieval field such as non-unique TutorGroup"], ["B1", "secondary key need not be unique"], ["B1", "index maps field values to record locations to speed access"], ["B1", "index requires storage and update maintenance"]], "Do not describe a secondary key as an alternate candidate key or require it to be unique."),

  r(81, ["S8.02"], "Relationships, foreign keys and referential integrity", [
    "A foreign key is an attribute in one table that refers to a primary/candidate key in another table. Referential integrity requires every non-null foreign-key value to match an existing referenced key.",
    "A one-to-one relationship links one record on each side. A one-to-many relationship links one parent record to many child records. A many-to-many relationship is normally implemented through a linking entity/table that creates two one-to-many relationships. Referential integrity prevents orphan records: insert, update and delete operations may be rejected or handled by a defined cascade/null policy, but must not silently leave an invalid reference."
  ], "Delete a department", "If Employee.DepartmentID refers to Department.DepartmentID, deleting a department with employees would break referential integrity unless deletion is rejected or an authorised cascading policy handles dependent rows.", [
    q("Where is the referenced key stored?", "In the parent/referenced table."),
    q("What is an orphan record?", "A child record whose foreign key has no matching parent key."),
    q("How is a many-to-many relationship represented relationally?", "Use a linking table/entity containing foreign keys to both original entities."),
    q("Name one valid delete response.", "Reject the delete, cascade it, or set nullable foreign keys to null according to defined rules.")
  ], "Explain how a one-to-many relationship between Department and Employee is represented and protected.", [["B1", "one Department record may relate to many Employee records"], ["B1", "DepartmentID is the primary/candidate key in Department"], ["B1", "DepartmentID is a foreign key in Employee and may repeat"], ["B1", "each non-null foreign-key value must match an existing Department key"], ["B1", "referential integrity prevents orphan Employee records"]], "Do not accept that foreign-key values must be unique in the child table."),

  r(82, ["S8.03"], "Document a design with an E-R diagram", [
    "An entity-relationship (E-R) diagram documents a database design by showing the entities, their relevant attributes or keys, the relationships between entities and the relationship cardinality. Entity names should describe things about which the system stores multiple facts; attributes belong to the entity they describe.",
    "To produce an E-R diagram, extract entity candidates from the scenario, assign identifiers, connect only supported relationships and label cardinality as one-to-one, one-to-many or many-to-many. Resolve a many-to-many relationship with a linking entity when converting the design to relational tables. A diagram must preserve the stated business rules rather than inventing links from similar field names."
  ], "Model students joining clubs", "Draw Student(StudentID, Name) and Club(ClubID, ClubName). Because each student may join many clubs and each club may contain many students, add Membership(StudentID, ClubID, JoinDate) as a linking entity. The completed design has Student 1:M Membership and Club 1:M Membership.", [
    q("What four kinds of information should an E-R diagram communicate here?", "Entities, relevant attributes/keys, relationships and cardinality."),
    q("What relationship exists between one Customer and many Orders?", "One-to-many from Customer to Order."),
    q("Why add Membership between Student and Club?", "It resolves the many-to-many relationship into two one-to-many relationships."),
    q("Why is matching field spelling not enough to draw a relationship?", "The scenario/business rule must state or imply that the records are associated.")
  ], "A clinic stores Patients, Doctors and Appointments. Produce an E-R design in words or a labelled diagram and state the two relationship cardinalities.", [["B1", "identifies Patient, Doctor and Appointment as entities"], ["B1", "gives a suitable identifier/key for each entity"], ["B1", "Patient has a one-to-many relationship with Appointment"], ["B1", "Doctor has a one-to-many relationship with Appointment"], ["B1", "Appointment carries the linking foreign keys / resolves the patient-doctor many-to-many history"], ["B1", "attributes and relationship directions are consistent with the scenario"]], "Do not award a collection of unconnected entity boxes as a complete E-R design."),

  r(83, ["S8.04"], "First, second and third normal form", [
    "1NF requires atomic values and no repeating groups. 2NF is 1NF with every non-key attribute dependent on the whole primary key, removing partial dependencies. 3NF is 2NF with no non-key attribute dependent on another non-key attribute, removing transitive dependencies.",
    "Normalisation decomposes tables while preserving keys and relationships. A normalised 3NF design stores each fact once in the table identified by its determinant, reducing insertion, update and deletion anomalies."
  ], "Order line data", "ORDER_LINE(OrderID, ProductID, ProductName, Quantity) has composite key OrderID+ProductID. ProductName depends only on ProductID, so split PRODUCT(ProductID, ProductName) and ORDER_LINE(OrderID, ProductID, Quantity) to reach 2NF for that dependency.", [
    q("What does 1NF remove?", "Repeating groups and non-atomic/multiple values in one field."),
    q("What dependency violates 2NF?", "A non-key attribute depending on only part of a composite key."),
    q("What dependency violates 3NF?", "A non-key attribute depending on another non-key attribute.")
  ], "Explain why CUSTOMER(CustomerID, Postcode, Town) may not be in 3NF when each postcode determines one town, and give a 3NF design.", [["B1", "CustomerID determines Postcode and Postcode determines Town"], ["B1", "Town is transitively dependent on CustomerID / depends on non-key Postcode"], ["A1", "CUSTOMER(CustomerID, Postcode)"], ["A1", "POSTCODE(Postcode, Town), with Postcode linked as foreign key"]], "Do not award decomposition marks unless primary/foreign-key linkage can reconstruct the relationship."),

  r(84, ["S8.08"], "Read and write SQL statements by their semantics", [
    "Structured Query Language (SQL) is the industry-standard language used by a DBMS for DDL and DML. To understand a statement, read each clause by its effect: SELECT chooses output fields, FROM identifies the source table, and WHERE filters records using a condition. Keywords, field names, table names, operators, literal values and punctuation have different roles.",
    "A valid answer must preserve the requested semantics, not merely contain familiar keywords. Text and date values are normally quoted in this course's standard SQL style; numeric and Boolean values are not quoted. Clause order, comparison operators and requested output fields determine which records and columns appear."
  ], "Interpret a query", "SELECT Title, DueDate FROM Loan WHERE Returned = FALSE; reads records from Loan, keeps only records whose Returned field is false, and outputs Title and DueDate. It does not update the table and it does not output every field.", [
    q("What does SELECT control?", "The fields or expressions shown in the result."),
    q("What does FROM control?", "The table supplying the records."),
    q("What does WHERE control?", "Which records satisfy the filter condition."),
    q("Why is SELECT * not equivalent to SELECT Title?", "The asterisk outputs all fields; SELECT Title outputs only the requested field.")
  ], "Explain the effect of SELECT StudentID, Name FROM Student WHERE TutorGroup = '12A'; and identify one change that would alter its result.", [["B1", "reads records from Student"], ["B1", "filters to TutorGroup 12A"], ["B1", "outputs StudentID and Name only"], ["B1", "identifies a valid semantic change such as field list, condition, operator or literal"], ["B1", "explains how the named change alters rows or columns returned"]], "Do not award a clause-name list unless its effect on this statement is explained."),

  r(86, ["S8.10"], "Two-table INNER JOIN queries", [
    "AS DML questions use at most two tables. Write an explicit INNER JOIN between those tables and place the matching key condition after ON; use table-qualified field names where the same field name could be ambiguous.",
    "For Student(StudentID, StudentName) and Loan(StudentID, DueDate), SELECT Student.StudentName FROM Student INNER JOIN Loan ON Student.StudentID = Loan.StudentID returns names only where matching rows exist. Add WHERE for a further row condition, not for the join relationship itself."
  ], "List overdue borrowers", "SELECT Student.StudentName FROM Student INNER JOIN Loan ON Student.StudentID = Loan.StudentID WHERE Loan.DueDate < '2027-05-01'; uses two tables, one explicit join condition and one separate filter.", [
    q("Which clause states how two joined tables match?", "ON."),
    q("How many tables are required at most in the AS syllabus query?", "Two."),
    q("Why qualify Student.StudentID and Loan.StudentID?", "To identify which table supplies each otherwise identical field name.")
  ], "Write an INNER JOIN query listing DepartmentName and EmployeeName from Department and Employee, matching their DepartmentID fields.", [["B1", "SELECT includes DepartmentName and EmployeeName"], ["B1", "FROM Department"], ["B1", "INNER JOIN Employee"], ["B1", "ON Department.DepartmentID = Employee.DepartmentID"]], "Do not use a three-table query or replace the required INNER JOIN with comma-style FROM and a WHERE join."),

  r(87, ["S8.07", "S8.09", "S8.11"], "DDL, DML and the complete AS SQL subset", [
    "A DBMS carries out creation or modification of database structure using Data Definition Language (DDL). Required DDL includes CREATE DATABASE, CREATE TABLE and ALTER TABLE. Table definitions may use CHARACTER, VARCHAR(n), BOOLEAN, INTEGER, REAL, DATE and TIME, plus PRIMARY KEY(field) and FOREIGN KEY(field) REFERENCES Table(Field).",
    "A DBMS carries out queries and maintenance of stored data using Data Manipulation Language (DML). SELECT queries data; INSERT INTO adds records; UPDATE changes existing records; DELETE FROM removes records. SQL is the industry-standard language for both DDL and DML. WHERE must be used when only selected existing records should be updated or deleted."
  ], "Define a database and maintain its data", "CREATE DATABASE College; creates the database structure. CREATE TABLE Department (DepartmentID INTEGER, Code CHARACTER, Name VARCHAR(40), Open BOOLEAN, Budget REAL, ReviewDate DATE, StartTime TIME, PRIMARY KEY (DepartmentID)); defines a table. ALTER TABLE Department ADD ManagerID INTEGER; changes the structure. INSERT INTO, UPDATE and DELETE FROM then maintain records rather than redefining the table.", [
    q("Classify CREATE TABLE and ALTER TABLE as DDL or DML.", "DDL, because they define or change structure."),
    q("Name all seven required DDL data types.", "CHARACTER, VARCHAR(n), BOOLEAN, INTEGER, REAL, DATE and TIME."),
    q("Which commands add, change and remove stored records?", "INSERT INTO, UPDATE and DELETE FROM."),
    q("Write the foreign-key clause for DepartmentID referencing Department(DepartmentID).", "FOREIGN KEY (DepartmentID) REFERENCES Department (DepartmentID)."),
    q("Why can UPDATE or DELETE without WHERE be dangerous?", "It can affect every record in the table.")
  ], "Write SQL to create Event(EventID, Code, Title, EventDate, StartTime, Open, Price), make EventID the primary key, then insert one record and update its Price.", [["B1", "CREATE TABLE Event with a valid field list"], ["B1", "uses INTEGER for EventID and PRIMARY KEY (EventID)"], ["B1", "uses CHARACTER or VARCHAR(n) appropriately for Code/Title"], ["B1", "uses DATE, TIME, BOOLEAN and REAL for the remaining named fields"], ["B1", "valid INSERT INTO with matching fields and values"], ["B1", "valid UPDATE Event SET Price = value WHERE EventID = value"]], "Do not substitute UPDATE for ALTER TABLE or treat INSERT, UPDATE and DELETE as structure-definition commands."),

  r(89, ["S8.01", "S8.02", "S8.03", "S8.04", "S8.05", "S8.06", "S8.07", "S8.08", "S8.09", "S8.10", "S8.11"], "Section 8 required-content checkpoint", [
    "Database design review: connect each file-based limitation to a relational or DBMS mechanism; use entity/table, record/tuple and field/attribute precisely; distinguish candidate, primary, secondary and foreign keys; classify one-to-one, one-to-many and many-to-many relationships; apply referential integrity and indexing; document the design with an E-R diagram; and explain or produce 1NF, 2NF and 3NF designs.",
    "DBMS and SQL review: identify data management/data dictionary, data modelling, logical schema, integrity, security/backup/access rights, developer interface and query processor. Distinguish DDL structure commands from DML query/maintenance commands, use every required data type and key clause, and keep SELECT queries to at most two tables with explicit INNER JOIN ... ON when two tables are needed.",
    "A complete answer follows the scenario through design, statement and result. It does not claim that a primary key prevents every duplicate fact, that a secondary key must be unique, that normalisation guarantees correctness, or that a three-table/comma-style query is within the AS core boundary."
  ], "Design and query a library database", "Separate Student and Loan tables, identify StudentID as primary key in Student and foreign key in Loan, state the one-to-many relationship and referential-integrity rule, then write SELECT Student.StudentName, Loan.DueDate FROM Student INNER JOIN Loan ON Student.StudentID = Loan.StudentID WHERE Loan.Returned = FALSE; using exactly two tables.", [
    q("Which key may retrieve several records sharing a value?", "A secondary key; it need not be unique."),
    q("Which normal form removes partial dependency on part of a composite key?", "Second Normal Form (2NF)."),
    q("Which two DBMS tools are named separately in the syllabus?", "Developer interface and query processor."),
    q("Which SQL language category changes table structure?", "DDL."),
    q("What is the AS table-count boundary for a DML query?", "At most two tables.")
  ], "A school currently repeats student details in a loan file. Propose a relational design and write a two-table query listing StudentName and DueDate for unreturned loans.", [["B1", "identifies redundancy/inconsistency in the repeated file"], ["B1", "separates Student and Loan with suitable primary keys"], ["B1", "uses StudentID as a foreign key in Loan and preserves referential integrity"], ["B1", "SELECT contains StudentName and DueDate"], ["B1", "uses Student INNER JOIN Loan"], ["B1", "ON matches Student.StudentID to Loan.StudentID"], ["B1", "WHERE Loan.Returned = FALSE"]], "Do not accept a three-table query, comma-style join, unexplained table split or unsupported claim that normalisation alone validates every value."),

  r(98, ["S9.03", "S9.04", "S9.05"], "Algorithms, IPO solutions and identifier tables", [
    "An algorithm is a solution to a problem expressed as a sequence of defined steps. Each step must be unambiguous, ordered where order matters and capable of being carried out; a vague instruction such as 'process the data' is not a defined step.",
    "Before writing pseudocode, identify the input data, the processing that transforms it and the required output. This input-process-output design must describe a complete solution rather than three unrelated lists.",
    "Choose meaningful identifier names that describe each value's role. An identifier table records at least the identifier name, data type and purpose; its entries must match the pseudocode solution."
  ], "Define and plan a ticket algorithm", "Problem: input TicketCount and TicketPrice, then output TotalCost. The algorithm is the defined sequence INPUT TicketCount; INPUT TicketPrice; TotalCost <- TicketCount * TicketPrice; OUTPUT TotalCost. The identifier table records TicketCount: INTEGER, number requested; TicketPrice: REAL, price of one ticket; TotalCost: REAL, calculated cost.", [
    q("What is an algorithm?", "A solution to a problem expressed as a sequence of defined steps."),
    q("State the input, process and output for rectangle area.", "Inputs Length and Width; process multiply Length by Width; output Area."),
    q("Improve identifier x for the number of absent students and state its type.", "AbsentCount or NumberAbsent, with type INTEGER.")
  ], "Construct an identifier table and an input-process-output pseudocode solution that inputs a student's name and three marks, then outputs the calculated mean.", [["B1", "meaningful STRING identifier and purpose for the student's name"], ["B1", "three clearly identified numeric mark inputs or a clearly bounded mark collection"], ["B1", "meaningful REAL identifier and purpose for the mean"], ["B1", "pseudocode inputs the required values"], ["B1", "processing calculates the total and mean in a defined sequence"], ["B1", "outputs the calculated mean and matches the identifier table"]], "Do not award an identifier list without types and purposes, or IPO headings without a complete sequence of defined steps."),

  r(99, ["S9.01", "S9.02"], "Abstraction and decomposition into program modules", [
    "Abstraction removes each irrelevant detail that does not affect the required inputs, rules, constraints or outputs. Producing an abstract model means recording the essential details that remain: the data, relationships and processes needed to solve the problem, not merely listing what was ignored.",
    "Decomposition breaks a problem into smaller sub-problems with distinct responsibilities. Express the resulting design as program modules with clear inputs, processing and outputs; a module may later be implemented as a procedure that performs an action or a function that returns a value.",
    "Abstraction decides what belongs in the model; decomposition decides how the retained problem is divided. The modules must connect into one complete solution and must not omit a requirement."
  ], "Model and decompose a car-park charge", "Keep entry time, exit time and tariff; omit car colour because it cannot change the charge. Express the solution as modules InputTimes, CalculateDuration, CalculateCharge and OutputCharge. CalculateCharge can become a function returning the charge, while OutputCharge can become a procedure that displays it.", [
    q("What must an abstract model contain?", "The essential details and relationships/processes needed to solve the problem."),
    q("What does decomposition produce here?", "Smaller sub-problems expressed as connected program modules with clear responsibilities."),
    q("Distinguish a procedure module from a function module at this design stage.", "A procedure performs an action; a function returns a value to its caller.")
  ], "Produce an abstract model for a school meal bill, then decompose it into named program modules and identify one likely procedure and one likely function.", [["B1", "retains meal choice, quantity and price as essential details"], ["B1", "states the calculation and total output in the abstract model"], ["B1", "excludes a justified irrelevant detail such as tray colour"], ["B1", "expresses the problem as connected modules with distinct responsibilities"], ["B1", "identifies a suitable procedure module that performs an action"], ["B1", "identifies a suitable function module that returns a value"]], "Do not award only a list of omitted details, vague Part1/Part2 labels or modules that do not collectively solve the problem."),

  r(100, ["S9.06"], "Sequence, selection and iteration", [
    "Sequence executes defined steps once in order. Selection chooses one of two or more paths using a condition. Iteration repeats one or more steps using a count or a condition.",
    "A complete algorithm often combines the three constructs: use sequence to initialise and input, iteration to process repeated items, and selection inside the loop when each item needs a decision.",
    "Choose the construct from the required behaviour. A known number of repetitions suggests count-controlled iteration; a stopping rule based on data suggests condition-controlled iteration."
  ], "Count five passing marks", "Sequence sets PassCount to 0. A FOR loop iterates through five marks. Inside the loop, selection tests Mark >= 50 and increments PassCount only on the true path. Sequence after the loop outputs PassCount.", [
    q("Which construct executes steps once in a fixed order?", "Sequence."),
    q("Which construct chooses between Pass and Resit?", "Selection."),
    q("Which construct processes ten supplied readings?", "Iteration, normally a count-controlled loop because the number is known.")
  ], "Design a short algorithm that inputs ten marks and outputs how many are passes, labelling where sequence, selection and iteration are used.", [["B1", "sequence initialises the pass count"], ["B1", "iteration processes exactly ten marks"], ["B1", "selection tests each mark against the pass condition"], ["B1", "sequence outputs the final count after the loop"]], "Do not award a construct name unless the stated algorithm uses it for the correct behaviour."),

  r(101, ["S9.07"], "Structured English, flowcharts and pseudocode conversion", [
    "Structured English expresses sequence, selection and repetition using controlled natural-language statements and indentation. A flowchart uses standard symbols and arrows; pseudocode uses Cambridge constructs. All three must preserve the same decisions and loop boundaries.",
    "Convert by identifying inputs, outputs, conditions and repeated actions before translating notation. Do not translate shapes or sentences word for word while losing control flow."
  ], "Validate a mark", "Structured English: INPUT Mark; WHILE Mark < 0 OR Mark > 100, OUTPUT error and INPUT Mark; ENDWHILE. The flowchart returns from the invalid decision branch to input; pseudocode uses a pre-condition WHILE loop.", [
    q("Which flowchart symbol represents a decision?", "Diamond."),
    q("What must remain identical during conversion?", "The algorithm's control flow, conditions, inputs and outputs."),
    q("Why is indentation useful in structured English?", "It shows which steps belong inside a selection or loop.")
  ], "Convert this structured English to pseudocode: input Age; if Age is at least 18 output Adult, otherwise output Minor.", [["B1", "INPUT Age"], ["B1", "IF Age >= 18 THEN"], ["B1", "OUTPUT Adult and ELSE OUTPUT Minor"], ["B1", "closes with ENDIF / coherent Cambridge syntax"]], "Do not accept two independent IF statements if they can produce contradictory paths; the description requires mutually exclusive alternatives."),

  r(104, ["S10.03", "S10.06"], "Array model required by search algorithms", [
    "Before tracing a search, define the data structure it traverses. An array is a fixed-size indexed collection whose elements have one declared data type. The index selects one element; it is not the value stored in that element.",
    "Cambridge pseudocode declares explicit inclusive bounds. In DECLARE Names : ARRAY[1:4] OF STRING, 1 is the lower bound, 4 is the upper bound and the valid indexes are 1, 2, 3 and 4. A search must start and stop within those declared bounds.",
    "Linear search checks successive indexed elements until the target is found or every populated element has been checked. Binary search also uses indexes, but requires the array to be sorted so each comparison can discard one half of the remaining index range."
  ], "Declare the search data before tracing it", "DECLARE Names : ARRAY[1:4] OF STRING defines four string elements. For Names = ['Asha', 'Ben', 'Chen', 'Dina'], a one-based linear search compares Names[1], then Names[2], and stops when it finds 'Ben'. Index 0 is invalid because it is below the declared lower bound.", [
    q("What are the lower and upper bounds of ARRAY[1:4]?", "The lower bound is 1 and the upper bound is 4."),
    q("What does Names[Index] mean?", "The single array element selected by the current value of Index."),
    q("Why must binary search know the current Low and High indexes?", "They delimit the remaining sorted portion of the array that may contain the target.")
  ], "Declare an array called Code that stores 20 STRING values, then state the first and last valid indexes used by a search.", [["B1", "DECLARE Code : ARRAY[1:20] or another explicit 20-element bound range"], ["B1", "OF STRING"], ["B1", "first valid index matches the declared lower bound"], ["B1", "last valid index matches the declared upper bound"]], "Do not assume zero-based indexing when the declaration gives different bounds."),

  r(102, ["S9.09"], "Logic statements define parts of an algorithm", [
    "A logic statement defines a decision, repetition condition or Boolean assignment in an algorithm solution. It combines comparisons such as =, <, <=, >, >= or <> with AND, OR or NOT when more than one condition is needed.",
    "Construct a statement from the rule before choosing its branch: a valid mark from 0 to 100 inclusive is Mark >= 0 AND Mark <= 100. Interpret it by checking both comparisons; using OR would accept values outside the range.",
    "Logic statements must preserve boundaries and intended truth conditions. Trace representative true, false and boundary values to expose reversed operators or incorrect connectors."
  ], "Define a valid-age condition", "For an accepted age from 11 to 18 inclusive, use Age >= 11 AND Age <= 18. At Age = 11 and Age = 18 the statement is TRUE; at Age = 10 or 19 it is FALSE. NOT(Age >= 11 AND Age <= 18) describes the invalid case.", [
    q("Construct the valid-mark statement for 0 to 100 inclusive.", "Mark >= 0 AND Mark <= 100."),
    q("Interpret Found = FALSE OR Index <= UpperBound.", "The statement is true when the target has not been found, or the index is still within the upper bound, or both."),
    q("Why is Mark >= 0 OR Mark <= 100 incorrect for validation?", "Every number satisfies at least one side, so out-of-range values can be accepted.")
  ], "Write and explain a logic statement that accepts an integer Temperature from -20 to 50 inclusive, then state its value for -21, -20, 50 and 51.", [["B1", "uses Temperature >= -20"], ["B1", "uses AND Temperature <= 50"], ["B1", "states FALSE for -21"], ["B1", "states TRUE for -20 and 50"], ["B1", "states FALSE for 51"]], "Do not accept OR for a two-bound inclusive range or award outputs without a correctly constructed statement."),

  r(111, ["S9.02", "S9.05", "S9.08"], "Stepwise refinement from IPO design to modules", [
    "Stepwise refinement starts with a high-level algorithm and repeatedly replaces each complex step with a smaller sequence of defined substeps. Refinement stops when every step is precise enough to implement and its input and output are clear.",
    "At each level, preserve the parent step's purpose and input-process-output relationship. Related substeps can be expressed as program modules, including procedures that perform actions and functions that return calculated values.",
    "Refinement supports review, implementation and testing because each module has a limited responsibility. It is not merely adding prose: every level must reduce ambiguity and collectively remain a complete solution."
  ], "Refine an order-processing algorithm", "Level 1: InputOrder; ValidateOrder; CalculateTotal; ProduceReceipt. Refine CalculateTotal into Set Total to 0; for each item validate Quantity; add Price * Quantity; apply Discount; return Total. CalculateTotal can be a function returning Total, while ProduceReceipt can be a procedure receiving the completed total.", [
    q("What is the starting point of stepwise refinement?", "A high-level algorithm or task."),
    q("When should refinement stop?", "When each step is a defined, implementable action with clear inputs and outputs."),
    q("How does IPO help one refinement level?", "It checks that each module receives the data it needs, performs defined processing and supplies the required output.")
  ], "Apply two levels of stepwise refinement to 'register a new library member', showing module inputs/outputs and identifying one procedure or function.", [["B1", "Level 1 separates capture, validation, storage and confirmation responsibilities"], ["B1", "Level 2 replaces at least one complex step with smaller ordered substeps"], ["B1", "module inputs and outputs are clear"], ["B1", "procedure or function choice matches action versus returned value"], ["B1", "refined steps collectively implement the original task"]], "Do not award unrelated features, repeated high-level labels or a level that does not reduce ambiguity."),

  r(112, ["S9.01", "S9.02", "S9.03", "S9.04", "S9.05", "S9.06", "S9.07", "S9.08", "S9.09"], "Section 9 required-content checkpoint", [
    "Algorithm design review: define an algorithm as a solution expressed as a sequence of defined steps; use abstraction to retain essential details in an abstract model; use decomposition to express the problem as connected modules; and choose meaningful identifiers recorded in an identifier table.",
    "Solution review: design with input-process-output, use sequence, selection and iteration, document the same algorithm in structured English, a flowchart or pseudocode, and convert between the specified representations without changing its control flow.",
    "Development review: use stepwise refinement until steps are programmable, and construct and interpret logic statements that define decisions, loop conditions or Boolean values. Core answers must not replace these requirements with tracing, Java syntax or vague planning advice."
  ], "Design a result-processing solution", "Keep only student ID and required marks, decompose the task into InputResults, ValidateResult, CalculateMean and OutputReport, record meaningful identifiers and IPO, refine CalculateMean into defined steps, use a range logic statement, and represent the final control flow in Cambridge pseudocode or a matching flowchart.", [
    q("State the official-style definition of an algorithm.", "A solution to a problem expressed as a sequence of defined steps."),
    q("What is the difference between abstraction and decomposition?", "Abstraction selects essential details for the model; decomposition splits the retained problem into sub-problems/modules."),
    q("What must remain unchanged when converting representations?", "The algorithm's inputs, outputs, conditions, order, branches and loop behaviour.")
  ], "Design an abstract, modular algorithm for processing ten valid marks, then show one refinement level and the central validation logic statement.", [["B1", "abstract model keeps only essential data, rules and output"], ["B1", "decomposition expresses connected program modules"], ["B1", "identifier table uses meaningful names, types and purposes"], ["B1", "IPO design forms a complete solution"], ["B1", "sequence, selection and iteration are used appropriately"], ["B1", "one representation is accurate and convertible without changing meaning"], ["B1", "stepwise refinement replaces a complex step with implementable substeps"], ["B1", "logic statement correctly enforces the required mark range"]], "Do not award isolated terminology when the design omits the required model, modules, refinement or logic."),

  r(105, ["S10.06"], "Write linear-search and bubble-sort algorithms", [
    "Linear search examines array elements in index order until the target is found or all populated elements have been checked. A complete algorithm initialises its index and found state, keeps every access within the declared bounds, compares the current element and advances only when another element remains to be checked.",
    "Bubble sort makes repeated passes through the unsorted part of an array. Each pass compares adjacent elements and swaps them when they are in the wrong order. After a complete ascending pass, the largest remaining value is at the high end; the algorithm repeats until the required passes are complete or a whole pass makes no swaps.",
    "A trace is evidence about one execution, but the syllabus requires candidates to write the algorithms. The answer must therefore include initialisation, loop bounds, comparison, update or swap, and a valid stopping condition rather than only showing one example pass."
  ], "Two complete array algorithms", "A linear search of Code[1:Count] sets Found to FALSE and Index to 1, then compares Code[Index] with Target while Found is FALSE and Index is within Count. A bubble sort of Value[1:Count] uses nested passes, compares Value[Index] with Value[Index + 1], swaps an inverted pair through Temp and may stop early when a pass makes no swaps.", [
    q("When must a linear search stop?", "When the target has been found or every populated element within the declared bounds has been checked."),
    q("What comparison is made by an ascending bubble sort?", "Compare adjacent elements and swap when the left element is greater than the right element."),
    q("What does a no-swap pass prove?", "No adjacent pair is out of ascending order, so the array is sorted and the algorithm may stop.")
  ], "Write Cambridge pseudocode for a linear search of Name[1:20] and an ascending bubble sort of Score[1:20].", [["B1", "linear search initialises Found and Index"], ["M1", "linear search loops within indexes 1 to 20 until found or exhausted"], ["A1", "linear search compares Name[Index] with the target and records a match"], ["B1", "bubble sort uses repeated passes"], ["M1", "compares adjacent Score[Index] and Score[Index + 1] within valid bounds"], ["M1", "uses Temp or an equivalent safe three-step swap"], ["A1", "reduces the unsorted range or uses a valid no-swap stopping condition"], ["B1", "all constructs close coherently in Cambridge pseudocode"]], "Do not award only a trace or a description; both requested algorithms must be written and must not access Index + 1 beyond the upper bound."),

  r(113, ["S10.01"], "Select and use the official Cambridge data types", [
    "Select a type from the meaning and operations required by the problem. INTEGER stores whole numbers, REAL stores values that may contain a fractional part, CHAR stores one character, STRING stores a sequence of characters, BOOLEAN stores TRUE or FALSE, and DATE stores a calendar date.",
    "Cambridge pseudocode uses the type names INTEGER, REAL, CHAR, STRING, BOOLEAN, DATE, ARRAY and FILE. ARRAY and FILE describe structured or persistent data; their declarations also state an element type, bounds or file usage as required by the problem.",
    "An identifier that contains digits is not automatically INTEGER. Codes, telephone numbers and identifiers with leading zeroes normally use STRING because arithmetic is not required. Type selection does not replace validation of permitted values."
  ], "Choose types for a booking", "Use STRING for BookingCode because it may contain letters or leading zeroes; DATE for VisitDate; INTEGER for TicketCount; REAL for TotalCost; CHAR for a one-letter Zone; BOOLEAN for HasPaid; ARRAY for a fixed indexed set of attendee names; and FILE when bookings must persist between program runs.", [
    q("Choose a type for the initial M.", "CHAR, because exactly one character is stored."),
    q("Choose a type for 18.75 used in arithmetic.", "REAL, because the value has a fractional part."),
    q("Why is 0045A a STRING?", "It is an identifier containing a letter and significant leading zeroes, and arithmetic is not required."),
    q("Name the eight type names listed in the syllabus Notes.", "INTEGER, REAL, CHAR, STRING, BOOLEAN, DATE, ARRAY and FILE.")
  ], "Select and justify suitable Cambridge types for CustomerName, MiddleInitial, DateJoined, ItemCount, MeanScore, IsActive, twenty marks and data that must remain after the program ends.", [["B1", "STRING for CustomerName"], ["B1", "CHAR for MiddleInitial"], ["B1", "DATE for DateJoined"], ["B1", "INTEGER for ItemCount"], ["B1", "REAL for MeanScore"], ["B1", "BOOLEAN for IsActive"], ["B1", "ARRAY with a numeric element type for twenty indexed marks"], ["B1", "FILE for persistent data, with justifications linked to meaning or use"]], "Do not select a numeric type merely because an identifier contains digits, and do not use STRING as a generic replacement for DATE, CHAR or numeric values that require their defined operations."),

  r(115, ["S10.03", "S10.04", "S10.05"], "Array terminology, selection and one-dimensional pseudocode", [
    "An array is a collection of elements stored under one identifier. An index selects one element. The lower bound is the first valid index and the upper bound is the last valid index; both bounds are inclusive in a Cambridge declaration such as ARRAY[1:20] OF INTEGER.",
    "Choose a one-dimensional array when each element needs one position, such as twenty marks or a list of names. Choose a two-dimensional array when each value naturally needs a row and a column, such as marks for several students across several tests. Do not choose 2D merely because there are many values.",
    "One-dimensional array pseudocode must declare explicit bounds and an element type, access elements with one index and use loop bounds that match the declared lower and upper bounds. The number of elements is upper bound - lower bound + 1."
  ], "Choose and declare the dimension", "Twenty daily temperatures need one position per day, so DECLARE Temperature : ARRAY[1:20] OF REAL is suitable and valid indexes are 1 to 20. Marks for 30 students in 4 tests need row and column positions, so a 2D array is suitable instead.", [
    q("Define index, lower bound and upper bound.", "An index selects an element; the lower bound is the first valid index; the upper bound is the last valid index."),
    q("Choose 1D or 2D for twelve monthly rainfall totals.", "1D, because one month index selects each total."),
    q("Write a declaration for 50 Boolean flags and state the number of elements.", "DECLARE Flag : ARRAY[1:50] OF BOOLEAN; there are 50 elements.")
  ], "Declare a one-dimensional array for 25 REAL measurements, input every element and explain why a two-dimensional array is not required.", [["B1", "DECLARE Measurements : ARRAY[1:25]"], ["B1", "OF REAL"], ["M1", "FOR loop uses the declared lower and upper bounds"], ["A1", "INPUT Measurements[Index] and closes with NEXT Index"], ["B1", "one index identifies each measurement"], ["B1", "there is no row-column relationship requiring a second dimension"]], "Do not use index 0 when the declared lower bound is 1, and do not describe bounds as stored element values."),

  r(116, ["S10.04", "S10.05"], "Select and write two-dimensional arrays", [
    "A two-dimensional array uses two indexes, normally interpreted as row and column. In DECLARE Marks : ARRAY[1:30, 1:4] OF INTEGER, the first range gives 30 valid row indexes and the second gives 4 valid column indexes, for 120 cells.",
    "Select 2D when the scenario has two independent position dimensions, such as Student and Test, Row and Column, or Day and Period. A simple list, sequence or one category of positions remains 1D even when it contains many elements.",
    "Two-dimensional pseudocode declares both ranges, accesses one cell as Marks[Student, Test] and normally uses nested loops: one loop traverses rows and the inner loop traverses every column for the current row."
  ], "Input a student-by-test table", "DECLARE Marks : ARRAY[1:30, 1:4] OF INTEGER. Use FOR Student <- 1 TO 30 and inside it FOR Test <- 1 TO 4; INPUT Marks[Student, Test]; NEXT Test; NEXT Student. Every one of the 120 cells is visited exactly once.", [
    q("Why is a seating grid normally 2D?", "Each seat is identified by two independent positions: row and column."),
    q("How many cells are in ARRAY[1:3, 1:4]?", "12 cells because 3 row indexes are paired with 4 column indexes."),
    q("What is wrong with Marks[Row] for a 2D array?", "It supplies only one index and therefore does not identify a column or one complete cell.")
  ], "Write Cambridge pseudocode to declare a 5 by 7 REAL temperature table and calculate the total of every cell.", [["B1", "declares ARRAY[1:5, 1:7] OF REAL or equivalent explicit five-by-seven bounds"], ["B1", "initialises Total"], ["M1", "outer loop covers all five rows"], ["M1", "inner loop covers all seven columns"], ["A1", "adds Temperature[Row, Column] inside the inner loop"], ["B1", "closes both loops and outputs Total after traversal"]], "Do not reverse the declared bounds in the traversal or access a 2D cell with only one index."),

  r(118, ["S10.02"], "Define, read and save record data", [
    "A record structure groups a set of related fields, which may have different data types, under one identifier. Field names preserve the meaning of each value, so a record suits several facts about one entity better than an array of same-type indexed elements.",
    "Define a Cambridge record type with TYPE, field declarations and ENDTYPE. Declare record variables only after the type definition is complete. A complete definition states every field name and its type.",
    "Read data from a record by selecting a named field, for example OUTPUT Student1.Mark or CurrentMark <- Student1.Mark. Save data to the record by assigning to a named field, for example Student1.Mark <- 75. Reading or saving one field does not replace unrelated fields."
  ], "Define and use one student record", "TYPE TStudent declares Name : STRING, DateOfBirth : DATE, Mark : INTEGER and Enrolled : BOOLEAN, then closes with ENDTYPE. DECLARE Student1 : TStudent creates one record. Student1.Mark <- 75 saves a value to the Mark field; OUTPUT Student1.Mark reads that field.", [
    q("Why can a record contain both STRING and DATE fields?", "Record fields may have different data types but belong to one entity under one identifier."),
    q("Which statement saves a mark of 80?", "Student1.Mark <- 80."),
    q("Which expression reads the stored name?", "Student1.Name, for example OUTPUT Student1.Name.")
  ], "Define TProduct with Code, Description, Price and InStock fields, declare Product1, save values to Price and InStock, then read both fields.", [["B1", "opens TYPE TProduct and declares suitable named fields"], ["B1", "uses suitable STRING, REAL and BOOLEAN field types"], ["B1", "closes the definition with ENDTYPE"], ["B1", "declares Product1 : TProduct after ENDTYPE"], ["B1", "assigns/saves values through Product1.Price and Product1.InStock"], ["B1", "reads/outputs the two named fields without replacing other data"]], "Do not use numeric array indexing for record fields or omit ENDTYPE from the type definition."),

  r(120, ["S10.07"], "Why files are needed and how text-file pseudocode works", [
    "Variables, arrays and records in main memory normally lose their contents when a program ends or power is removed. Files provide persistent storage so data can be reloaded by a later run, transferred or shared as required. A file is not merely a larger array.",
    "For a text file containing one or more lines, select the mode before processing: READ obtains existing data, WRITE creates or replaces output content, and APPEND adds after existing content. Every opened file must be closed after processing.",
    "A complete read algorithm uses OPENFILE for READ, checks NOT EOF before READFILE, processes each line and then CLOSEFILE. WRITEFILE stores a line in a file opened for WRITE or APPEND. Reading after EOF or using WRITE when old content must remain are boundary errors."
  ], "Copy selected lines between text files", "Open Results.txt FOR READ and Pass.txt FOR WRITE. While NOT EOF(Results.txt), READFILE the next Line; if it contains PASS, WRITEFILE it to Pass.txt. Close both files after the loop. Results remain available from storage, while Pass.txt is deliberately created as a new output file.", [
    q("Why use a file instead of only an array?", "A file persists after the program ends and can be reloaded in a later run."),
    q("Which mode adds without replacing old lines?", "APPEND."),
    q("Why test NOT EOF before READFILE?", "It prevents an attempt to read beyond the final available line.")
  ], "Write Cambridge pseudocode to read every line from Input.txt, copy non-blank lines to Output.txt and close both files. Explain why the input data is stored in a file.", [["B1", "persistent/later-use need for the input file"], ["B1", "opens Input.txt FOR READ"], ["B1", "opens Output.txt FOR WRITE"], ["M1", "loops WHILE NOT EOF before READFILE"], ["A1", "writes only non-blank lines inside a coherent IF"], ["B1", "closes both files after the loop"]], "Do not test EOF after an invalid read or claim that WRITE preserves existing output-file contents."),

  r(122, ["S10.08", "S10.09", "S10.10"], "Abstract data types and array-based operations", [
    "An abstract data type (ADT) is a collection of data and a set of operations on those data. The permitted operations and their effects define the ADT; its internal storage can change without changing that behaviour. Stack, queue and linked list are examples of ADTs.",
    "A stack is LIFO: add with push and delete with pop at the top. A queue is FIFO: add with enqueue at the rear and delete with dequeue at the front. A linked list stores data plus a next pointer/index in each node; start identifies the first node and null ends the chain.",
    "All three can be implemented using arrays and state variables or indexes. Stack uses an array with a top/stack pointer; queue uses an array with front and rear; linked list uses Data and Next arrays (or an array of node records), start and a free list. Candidates must be able to add, edit and delete data conceptually, but the syllabus does not require pseudocode for these ADT operations.",
    "Editing changes the stored data without breaking the access rule or links. Deleting from a linked list reconnects the predecessor to the removed node's successor and returns the freed array slot to the free list; physical array positions need not follow logical list order."
  ], "Add, edit and delete without changing the ADT rule", "Push D adds D at the stack top and pop deletes the current top. Enqueue D adds at the queue rear and dequeue deletes from the front. In an array-based linked list, edit Data[5] to change only the node value; insert or delete by changing Next indexes, Start and the free list rather than shifting every later array item.", [
    q("Give the official definition of an ADT.", "A collection of data and a set of operations on those data."),
    q("How are stack and queue removal rules different?", "Stack removes the most recently added item (LIFO); queue removes the earliest added item (FIFO)."),
    q("Which state is needed for an array-based linked list?", "Data and Next storage, a Start index and normally a free-list index."),
    q("Must candidates write pseudocode for stack, queue and linked-list operations?", "No. They must be able to add, edit and delete data and describe array implementations, but operation pseudocode is not required by the syllabus.")
  ], "For array implementations of a stack, queue and linked list, describe how data is added, edited and deleted while preserving each ADT's rule.", [["B1", "stack push/pop uses the top position and stack pointer"], ["B1", "queue enqueue/dequeue uses rear and front in FIFO order"], ["B1", "linked-list add obtains a free index and changes links"], ["B1", "edit changes a stored data field without corrupting order or links"], ["B1", "linked-list delete bypasses the node and returns its index to the free list"], ["B1", "distinguishes conceptual operations from the non-required task of writing their pseudocode"]], "Do not define an ADT as only an array, require ADT-operation pseudocode, or delete a linked-list node without repairing its links and free-list state."),

  r(123, ["S10.09", "S10.10"], "Choosing stack, queue or linked list", [
    "A stack is LIFO with push/pop at the top; a queue is FIFO with enqueue at the rear and dequeue at the front; a linked list supports traversal and insertion/deletion through links.",
    "Justification must name the required access order or update behaviour. Array implementations have fixed capacity unless resized and require overflow/underflow checks; linked structures require pointer management."
  ], "Choose structures", "Undo history uses a stack because the most recent action is undone first. Print jobs use a queue because the earliest accepted job prints first. A changing ordered playlist can use a linked list for link-based insertion/deletion.", [
    q("Choose an ADT for breadth-first waiting jobs.", "Queue, because first in is first out."),
    q("Choose an ADT for nested function return addresses.", "Stack, because the most recent call returns first."),
    q("What must be checked before pushing to a full array stack?", "Overflow/capacity.")
  ], "Justify a suitable ADT for browser Back history and contrast it with a queue.", [["B1", "selects stack"], ["B1", "most recently visited page is returned to first / LIFO"], ["B1", "queue removes earliest item first / FIFO"], ["B1", "explains why FIFO gives the wrong access order"]], "Do not award the structure name without its access-order consequence."),

  r(114, ["S11.02"], "Complete Cambridge pseudocode statements", [
    "Section 11.1 requires pseudocode for the declaration and initialisation of constants, declaration of variables, assignment of values, arithmetic or logical expressions entered from the keyboard, and input to or output from the console. These are connected statements, not isolated vocabulary.",
    "CONSTANT defines and initialises a fixed named value. DECLARE gives a variable a name and data type. Assignment evaluates the expression on the right of <- and stores the result in the variable on the left. INPUT obtains a value from the keyboard; OUTPUT sends a value to the console.",
    "Arithmetic expressions use operators such as +, -, *, /, DIV and MOD. Logical expressions combine comparisons with AND, OR or NOT and produce BOOLEAN results. Use = for comparison and <- for assignment."
  ], "Declare, input, calculate and output", "CONSTANT PassMark = 50 defines and initialises a constant. DECLARE Mark : INTEGER and DECLARE Passed : BOOLEAN declare variables. INPUT Mark obtains keyboard input; Passed <- Mark >= PassMark assigns the result of a logical expression; OUTPUT Mark * 2 and OUTPUT Passed send arithmetic and Boolean results to the console.", [
    q("What is the difference between = and <-?", "= compares values; <- assigns the evaluated right-hand value to a variable."),
    q("Which statement obtains keyboard input?", "INPUT followed by the target variable."),
    q("What type of result does Mark >= PassMark produce?", "A BOOLEAN result, TRUE or FALSE.")
  ], "Write Cambridge pseudocode that defines and initialises constant TaxRate as 0.20, declares Price and Tax as REAL, inputs Price, assigns Price * TaxRate to Tax, and outputs Tax.", [["B1", "CONSTANT TaxRate = 0.20"], ["B1", "declares Price and Tax as REAL"], ["M1", "INPUT Price before the calculation"], ["M1", "Tax <- Price * TaxRate"], ["A1", "OUTPUT Tax after assignment"]], "Do not use = for assignment, omit the constant initial value, or replace INPUT/OUTPUT with Java library calls."),

  r(127, ["S11.04"], "Selection structures in Cambridge pseudocode", [
    "Use IF...THEN...ELSE...ENDIF when a Boolean condition selects between paths. An ELSE clause supplies the false path. In nested IF statements, every inner and outer IF must be closed and the indentation must show which ELSE belongs to which IF.",
    "Use CASE...OF...OTHERWISE...ENDCASE when one expression is compared with several discrete values. CASE is not a replacement for range or compound-condition decisions unless the stated values cover the requirement correctly."
  ], "Nested IF and CASE", "For a grade, an outer IF tests Mark >= 80; its ELSE contains an inner IF testing Mark >= 50; each IF closes with ENDIF. For a menu, CASE Choice OF maps 1, 2 and 3 to actions and OTHERWISE handles every unlisted value before ENDCASE.", [
    q("How many ENDIF statements close two nested IF statements?", "Two: one closes the inner IF and one closes the outer IF."),
    q("When is CASE suitable?", "When one expression has several discrete values that map to separate branches."),
    q("What handles an unlisted CASE value?", "OTHERWISE, followed by ENDCASE for the complete structure.")
  ], "Write Cambridge pseudocode that inputs Age and Member, outputs Adult member when Age is at least 18 and Member is TRUE, Adult non-member for other adults, and Child otherwise. Then state why nested IF is appropriate.", [["B1", "inputs/uses both Age and Member"], ["M1", "outer IF tests Age >= 18"], ["M1", "inner IF tests Member only on the adult path"], ["A1", "three outputs are attached to the correct branches"], ["B1", "closes both IF statements coherently"], ["B1", "justifies nested selection because the membership decision depends on the age decision"]], "Do not use CASE for overlapping ranges without a complete mapping or close two IF statements with only one ENDIF."),

  r(128, ["S11.04", "S11.05"], "Write and justify a count-controlled loop", [
    "A count-controlled loop uses FOR...TO...NEXT when the repetition count or inclusive counter range is known before the loop starts. The counter, start value and end value define the iterations; NEXT closes the loop.",
    "Match the loop bounds to the declared data. Initialise accumulators before the loop, update them inside it and output a final result after the loop unless intermediate output is explicitly required.",
    "Justify FOR from the problem: it is well suited when the count or bounds are known, but a pre-condition or post-condition loop is better when the number of repetitions depends on input or a stopping condition."
  ], "Total a fixed array", "For Marks[1:30], set Total <- 0, use FOR Index <- 1 TO 30, add Marks[Index] to Total, close with NEXT Index and output Total after all thirty elements have been processed.", [
    q("Why is FOR suitable for Marks[1:30]?", "The 30 iterations and valid index bounds are known before the loop starts."),
    q("Where is Total initialised?", "Once before the loop."),
    q("Which keyword closes the count-controlled loop?", "NEXT followed by the counter name.")
  ], "Write Cambridge pseudocode to input and total exactly 12 monthly values, then output the total. Explain why the selected loop is count-controlled.", [["B1", "initialises Total before repetition"], ["M1", "uses FOR Month <- 1 TO 12 or an equivalent twelve-iteration range"], ["M1", "inputs a value and adds it inside the loop"], ["A1", "closes with NEXT and outputs Total after the loop"], ["B1", "justifies FOR because the repetition count is known in advance"]], "Do not use an eleven- or thirteen-iteration bound or reset the accumulator inside the loop."),

  r(129, ["S11.04", "S11.05"], "Pre-condition, post-condition and loop choice", [
    "A WHILE...ENDWHILE loop is a pre-condition loop: it tests before the body and may run zero times. A REPEAT...UNTIL loop is a post-condition loop: it executes the body before testing and therefore runs at least once. A FOR...NEXT loop is count-controlled.",
    "Select and justify the loop structure from the problem: use FOR when the count is known, WHILE when execution may be unnecessary and continuation is tested first, and REPEAT when the body must run once before a stopping condition can be tested. The justification must use the scenario, not only say that one loop is easier."
  ], "Choose the loop from the stopping rule", "Input validation must request a value at least once, so REPEAT; INPUT Mark; UNTIL Mark >= 0 AND Mark <= 100 is suitable. Processing records while a file is not at EOF can use WHILE because an empty file may require zero iterations. Processing twelve months uses FOR because the count is fixed.", [
    q("Which structure may execute zero times?", "WHILE, because it tests its condition before the body."),
    q("Which structure must execute at least once?", "REPEAT...UNTIL, because it tests after the body."),
    q("Why is FOR suitable for twelve months?", "The twelve repetitions are known before execution.")
  ], "Choose and justify FOR, WHILE or REPEAT...UNTIL for (a) processing 50 array elements, (b) reading while a file is not at EOF, and (c) requesting a password at least once until correct.", [["B1", "FOR for 50 known elements"], ["B1", "justifies fixed count/bounds"], ["B1", "WHILE for the pre-tested EOF condition and possible empty file"], ["B1", "REPEAT...UNTIL for password input that must occur once"], ["B1", "distinguishes pre-condition, post-condition and count-controlled structures"]], "Do not select a loop only by its spelling or claim that WHILE always executes once."),

  r(130, ["S11.06", "S11.07", "S11.08"], "Procedures, functions and their interfaces", [
    "Define and use a procedure when an algorithm needs a named action. A procedure may have no parameters, one parameter or several parameters. BYVAL passes a value that the procedure can use without changing the caller's variable; BYREF gives access to the caller's variable so an assignment can persist after the call.",
    "Define and use a function when the caller needs one returned value. A function has a return type and RETURN statement; the call can appear in an expression, for example Total <- Price + CalculateVAT(Price). Use procedures for actions and functions for calculated, searched or checked values.",
    "A procedure header or function header names the subprogram and declares its parameters; a function header also declares its return type. The procedure/function interface is the information a caller needs to use the subprogram: its name, parameter list and types, and any returned value/type.",
    "A parameter is the named variable in the header, while an argument is the actual value or variable supplied at a call. RETURN sends a function value back to the caller; output displayed by a procedure is an effect, not a return value."
  ], "Use a procedure and a function", "PROCEDURE Increase(BYREF Number : INTEGER, BYVAL Amount : INTEGER) changes the caller's Number by Amount. FUNCTION CalculateVAT(Price : REAL) RETURNS REAL returns Price * 0.20, so Total <- Price + CalculateVAT(Price) uses the returned value in an expression. In Increase(Score, 5), Number and Amount are parameters while Score and 5 are arguments.", [
    q("When is a procedure appropriate?", "When the algorithm needs a named action rather than a returned value used in an expression."),
    q("What is the difference between BYVAL and BYREF?", "BYVAL supplies a value/copy; BYREF aliases the caller variable so changes can persist."),
    q("Where can a function call be used?", "Anywhere its returned value of the declared type is valid, including an expression."),
    q("What is included in a subprogram interface?", "Its name, parameters/types and any return value/type needed by a caller."),
    q("In IsPass(Score), which name is the argument?", "Score."),
    q("How does a function return differ from procedure output?", "RETURN supplies a value to the caller; OUTPUT displays data as an action.")
  ], "Define a procedure AddBonus(BYREF Mark : INTEGER, BYVAL Bonus : INTEGER), define a function IsPass(Mark : INTEGER) returning BOOLEAN, and use both from a caller with IsPass(Score) inside an IF expression. Identify headers, parameters, arguments and return value.", [["B1", "procedure header and coherent BYREF/BYVAL parameters"], ["B1", "procedure changes Mark using Bonus and closes correctly"], ["B1", "function header declares BOOLEAN return type"], ["B1", "function returns the result of the pass comparison"], ["M1", "caller supplies arguments and uses IsPass(Score) in an expression/condition"], ["B1", "correctly identifies parameter, argument and returned value terminology"]], "Do not use parameter and argument as synonyms, describe procedure output as a function return, or claim BYVAL changes the caller variable."),

  r(133, ["S11.03"], "Use supplied built-in and library routines", [
    "Use built-in functions and library routines exactly as defined. The syllabus states that any function not given in the Cambridge pseudocode guide will be provided, and string manipulation functions will always be given in the question. Students are not expected to memorise one unofficial substring API.",
    "Read the supplied function name, parameter order, position convention and returned type before using it. LENGTH is a familiar built-in example; LEFT, RIGHT, MID or SUBSTRING examples in this course illustrate a mechanism only when their definition and indexing convention are stated.",
    "A function call returns a value, so it can be assigned, compared, output or combined in an expression. Do not import Java's zero-based substring convention unless the question explicitly specifies it."
  ], "Apply a supplied string routine", "A question defines EXTRACT(Text, Start, Count) using positions starting at 1. LENGTH(\"NETWORK\") returns 7; EXTRACT(\"NETWORK\", 4, 2) returns \"WO\". Code <- EXTRACT(UCASE(Name), 1, 3) nests a supplied library routine inside an expression.", [
    q("Will an unfamiliar string manipulation function be supplied?", "Yes. The syllabus says string manipulation functions will always be given."),
    q("What must be checked before tracing EXTRACT?", "Its supplied parameter order, position/index convention and return definition."),
    q("May a returned string be assigned to a variable?", "Yes; a function return can be used wherever a compatible value is needed.")
  ], "A question defines TAKE(Text, Start, Count), with positions starting at 1. State LENGTH(\"ALGORITHM\"), state TAKE(\"ALGORITHM\", 3, 4), and write an assignment that converts the extracted text to upper case using supplied routine UCASE.", [["B1", "LENGTH result is 9"], ["B1", "TAKE result is GORI"], ["M1", "uses the supplied Start/Count convention rather than Java indexing"], ["A1", "assigns UCASE(TAKE(\"ALGORITHM\", 3, 4)) or equivalent to a variable"]], "Do not require memorisation of an unstated substring signature or import Java's zero-based indexes."),

  r(140, ["S11.01"], "Translate descriptions into Cambridge pseudocode", [
    "To translate a flowchart, follow arrows from Start, convert input/output symbols directly, convert diamonds into IF/CASE or loop conditions, and preserve every branch and reconnection. To translate structured English, identify its controlled verbs and indentation before selecting Cambridge constructs.",
    "The answer must be Cambridge pseudocode, not Java: use assignment arrow, THEN/ENDIF, FOR...NEXT, WHILE...ENDWHILE or REPEAT...UNTIL as appropriate. Trace both versions with the same data to confirm equivalence."
  ], "Flowchart sum loop", "A flowchart sets Total to 0 and repeats input/add until Value = -1. Pseudocode uses Total <- 0; REPEAT; INPUT Value; IF Value <> -1 THEN Total <- Total + Value; ENDIF; UNTIL Value = -1; OUTPUT Total.", [
    q("How is a flowchart decision normally translated?", "As a selection or loop condition, depending on where arrows reconnect."),
    q("What check confirms a translation is equivalent?", "Dry-run both with the same inputs and compare outputs/control path."),
    q("Should Java braces appear in a Cambridge pseudocode answer?", "No; use Cambridge keywords and terminators.")
  ], "Translate this structured-English design into Cambridge pseudocode: input five temperatures; count those below zero; output the count.", [["B1", "initialises count to 0"], ["M1", "uses a five-iteration count-controlled loop with INPUT"], ["M1", "tests Temperature < 0 and increments count"], ["A1", "outputs count after the loop with coherent Cambridge syntax"]], "Do not accept Java syntax such as int, braces or System.out as Cambridge pseudocode."),

  r(141, ["S11.09"], "Efficient pseudocode is purposeful, not merely short", [
    "Efficient pseudocode avoids unnecessary repeated work and selects a structure suited to the data and stopping rule. For example, total and count can be updated during one traversal instead of scanning the same array twice when both results are needed.",
    "Efficiency does not justify incorrect bounds, hidden assumptions or compressed code that cannot be traced. A strong answer remains clear: initialise once, access only valid data, avoid redundant calculations and use meaningful identifiers and coherent constructs.",
    "At AS Level, justify an improvement from the actual algorithm, such as fewer repeated passes or stopping a search once the target is found. Do not claim that shorter text alone proves a more efficient algorithm."
  ], "Count passes and total in one traversal", "Set Total and PassCount to 0 before one FOR loop through Marks[1:30]. Add each mark to Total and increment PassCount only when the mark is at least 50. Output both values after NEXT Index. This preserves clear control flow while avoiding a second full traversal.", [
    q("Why is one combined traversal more efficient than two separate full traversals here?", "The same 30 elements are read once while both required results are updated, avoiding a redundant second pass."),
    q("Does fewer lines always mean greater efficiency?", "No. The control flow and amount of work matter; compressed but repeated or incorrect work is not an improvement."),
    q("When may a search stop early?", "When the target has been found, provided the algorithm no longer needs to inspect later elements for another stated result.")
  ], "Rewrite an algorithm that first totals Marks[1:30] and then makes a second pass to count passes, using one clear traversal. Explain the efficiency improvement.", [["B1", "initialises Total and PassCount once before the loop"], ["M1", "uses one loop over valid indexes 1 to 30"], ["M1", "updates Total and conditionally updates PassCount inside that loop"], ["A1", "outputs both results after the loop"], ["B1", "explains that the rewrite removes a redundant second traversal without changing the result"]], "Do not award an efficiency claim based only on fewer written lines; the revised pseudocode must perform less repeated work and remain correct."),

  r(138, ["S12.09"], "Analyse and amend an existing program to enhance functionality", [
    "Analyse the supplied program before editing it: state its current purpose, inputs, outputs, data structures, control flow and assumptions. Trace representative data to identify where a new requirement belongs and record behaviour that must remain unchanged.",
    "Amend the existing program with the smallest coherent change that enhances functionality. Update related declarations, initialisation, processing and output together; preserve established interfaces unless the requirement needs an interface change; and keep Cambridge pseudocode constructs complete.",
    "Test the enhancement with data that exercises the new path and rerun regression tests for existing paths. Correcting a fault is corrective maintenance; adding or improving requested functionality is an enhancement and may be perfective maintenance."
  ], "Add a Merit count without breaking PassCount", "The existing program counts marks at least 50 in PassCount. Analysis shows one traversal already reads every mark, so declare and initialise MeritCount, add IF Marks[Index] >= 70 THEN MeritCount <- MeritCount + 1 ENDIF inside the same loop, and output both counters after the loop. Test 49, 50, 69 and 70 to cover unchanged pass behaviour and the new merit boundary.", [
    q("What should be recorded before changing existing code?", "Its purpose, inputs, outputs, relevant control/data flow, assumptions and behaviour that must remain unchanged."),
    q("Why rerun old tests after adding a feature?", "Regression tests check that the amendment has not broken existing behaviour."),
    q("How is an enhancement different from merely correcting a fault?", "An enhancement adds or improves required functionality; a correction restores behaviour that was already required.")
  ], "An existing program counts PassCount for Marks[1:30] where each mark is at least 50. Analyse where a new MeritCount for marks at least 70 should be added, write the amended declarations, initialisation, loop update and output, and name four boundary-focused test values.", [["B1", "analysis identifies the existing traversal and output that must remain"], ["B1", "declares and initialises MeritCount without removing PassCount"], ["M1", "increments MeritCount inside the existing traversal when mark is at least 70"], ["M1", "preserves the existing pass condition at 50 and outputs both results after the loop"], ["B1", "uses 49 and 50 to regression-test the pass boundary"], ["B1", "uses 69 and 70 to test the new merit boundary"]], "Do not accept a rewrite that removes the existing pass count, changes its boundary, or tests only the new feature."),

  r(142, ["S12.01"], "Waterfall, iterative and rapid application development", [
    "Waterfall completes planned stages largely in sequence and supports documentation and traceability, but late change can cause substantial rework. Iterative development builds and reviews repeated versions so evidence can refine later cycles.",
    "Rapid application development (RAD) uses rapid prototyping, time-boxed development and frequent user involvement to obtain feedback quickly. It can suit an interactive system with available users, but speed and repeated prototypes can conflict with exhaustive assurance or stable architecture. Agile is related extension context, not a replacement for the named RAD model."
  ], "Choose a lifecycle model", "For a small booking interface with available users and changing requirements, RAD can use a time-boxed prototype and immediate user feedback. For safety-critical stable requirements, waterfall's formal traceability may be more suitable than rapid prototyping.", [
    q("Name three defining features of RAD.", "Rapid prototyping, time-boxing and frequent user involvement/feedback."),
    q("Which model proceeds through planned sequential stages?", "Waterfall."),
    q("Why might RAD be unsuitable for a safety-critical system?", "Rapid cycles may not provide the exhaustive assurance and traceability required.")
  ], "Compare waterfall, iterative and RAD for a system whose users can review frequent prototypes.", [["B1", "waterfall uses planned sequential stages and formal documentation"], ["B1", "iterative development reviews repeated versions"], ["B1", "RAD uses rapid prototypes/time-boxing"], ["B1", "RAD uses frequent user involvement and is linked to the scenario"]], "Do not substitute Agile for RAD or describe all repeated development as the same model."),

  r(144, ["S12.02", "S12.03"], "Structure charts and state-transition diagrams", [
    "A structure chart documents decomposition into modules, procedures and functions. Boxes name modules; hierarchy lines show which module calls another; labelled arrows show data or control parameters passed between them. Its purpose is to communicate modular structure and interfaces before coding.",
    "To construct a structure chart, place the controlling module at the top, split the problem into one-responsibility subtasks, connect each caller to its called modules, and label every value passed. To derive equivalent pseudocode, turn each box into a complete PROCEDURE or FUNCTION header with corresponding parameters, add calls in the parent body with matching arguments, and preserve the shown hierarchy.",
    "A state-transition diagram documents how an algorithm or system changes between persistent states. Mark the start state; draw each state once; label directed transitions with the triggering event and any condition/action. It is not a flowchart of every processing statement."
  ], "Door controller: two design views", "A structure chart places ControlDoor above ReadCard(CardID), ValidateCard(CardID, IsValid) and SetLock(IsValid). Equivalent pseudocode declares those interfaces and calls them from ControlDoor with matching arguments. Separately, a state-transition diagram starts at Locked; validCard / unlock leads to Unlocked; timeout / lock returns to Locked.", [
    q("What does a box represent in a structure chart?", "A module, procedure or function."),
    q("How are parameters represented and then derived into pseudocode?", "Labelled arrows show values passed; the same values appear as parameters in the called header and arguments in the caller's call."),
    q("What labels a state transition?", "The triggering event and, where needed, a condition or action."),
    q("Why is a state-transition diagram not a flowchart?", "It records persistent states and event-labelled changes, not every processing step in sequence.")
  ], "For a login system, construct a structure chart in which Main calls ReadCredentials(UserID, Password) and CheckLogin(UserID, Password, IsValid), then derive equivalent subprogram headers and calls. Also construct a state-transition diagram with start state LoggedOut, valid login to LoggedIn, logout back to LoggedOut and three invalid attempts to Locked.", [["B1", "structure chart places Main above the two called modules"], ["B1", "parameter arrows label UserID, Password and IsValid coherently"], ["M1", "derived pseudocode contains matching complete headers and calls with arguments"], ["B1", "state diagram contains LoggedOut, LoggedIn and Locked with a start arrow"], ["B1", "valid login and logout transitions are directed correctly"], ["B1", "three invalid attempts transition from LoggedOut to Locked"]], "Do not accept a flowchart as either document; the structure chart requires module hierarchy and parameters, while the state-transition diagram requires states and event-labelled transitions."),

  r(145, ["S12.05", "S12.06"], "Testing methods, strategy and test plan", [
    "Dry run manually traces code; walkthrough is a structured peer review; white-box derives tests from internal paths; black-box derives tests from specifications. Integration tests combined modules, using a stub to imitate an unavailable called module.",
    "Alpha testing is performed internally before release; beta testing uses selected external users in realistic settings; acceptance testing checks the delivered system against agreed requirements. A strategy states levels/methods/responsibility, while a test plan records test ID, purpose, data, expected result, actual result and pass/fail."
  ], "Test login through review, construction, integration and release", "First dry-run the lockout counter and conduct a walkthrough in which peers inspect the algorithm. White-box tests cover true/false paths; black-box tests valid, invalid and boundary inputs from requirements. During integration, a stub returns simulated account results before the database is ready. Internal staff perform alpha testing, selected external users perform beta testing, and the customer performs acceptance testing against the agreed lockout behaviour.", [
    q("Which method derives tests from source-code paths?", "White-box testing."),
    q("Who normally performs beta testing?", "Selected external/end users in realistic use."),
    q("What does a stub replace?", "A called module/component not yet available.")
  ], "For a login system, produce a test strategy naming the review, structural, functional, integration and release/user-testing methods to be used and who is responsible. Then write one complete test-plan row containing test ID, purpose, data, expected result, actual result and pass/fail.", [["B1", "strategy includes dry run or walkthrough and white-box/black-box methods"], ["B1", "strategy includes integration with a stub where a called module is unavailable"], ["B1", "strategy distinguishes alpha, beta and acceptance testing with suitable responsibility"], ["B1", "test-plan row includes identifier/purpose and test data"], ["B1", "row states an expected result before execution"], ["B1", "row records actual result and pass/fail outcome"]], "Do not accept only normal/abnormal/boundary categories as a strategy or plan; methods, responsibility and a complete recorded test must be present."),

  r(146, ["S12.08"], "Continuing maintenance after delivery", [
    "Maintenance continues after delivery because faults are discovered, operating environments and rules change, and users request improvements. Corrective maintenance fixes faults in required behaviour; adaptive maintenance changes software for a new environment, platform, law or external rule; perfective maintenance improves functionality, usability, performance or maintainability.",
    "Classify the reason for the change, not the code edited. The same module could receive a corrective change for a crash, an adaptive change for a new operating-system interface, or a perfective change for faster search and a clearer result display.",
    "Every maintenance change requires impact analysis, controlled amendment, tests for the changed behaviour and regression tests for unaffected behaviour. Records should link the request, code change and test evidence."
  ], "Three changes to one booking system", "Fixing a crash when saving is corrective. Updating tax or term-date rules imposed externally is adaptive. Adding a wait-list search and making results faster is perfective. Each change is traced to a request and followed by targeted and regression tests.", [
    q("Why does maintenance continue after acceptance?", "Faults, environmental changes and requested improvements continue after delivery."),
    q("Which type changes software for a new external rule?", "Adaptive maintenance."),
    q("Which type adds useful functionality or improves performance?", "Perfective maintenance.")
  ], "Classify and justify these changes: fix a save crash; support a new operating-system API; add an export feature. For one change, state the impact-analysis and regression evidence required.", [["B1", "save-crash fix classified as corrective with fault reason"], ["B1", "new operating-system API classified as adaptive with environment reason"], ["B1", "new export feature classified as perfective with enhancement reason"], ["B1", "identifies affected interfaces/modules or behaviour before amendment"], ["B1", "tests the changed path"], ["B1", "reruns relevant existing tests to detect regression"]], "Do not classify every post-release change as adaptive or describe perfective maintenance as fault correction only."),
];
